export default [{"id":19,"question":"أيُّهما أفضل: مُجاهدة النفس بترك المعاصي، أو مُجاهدة أعداء الله بالمال والنفس؟ وأيُّهما أفضل: الجهاد بالمال أم الجهاد بالنفس؟ وهل يدخل الجهادُ باللسان والقلم في الجهاد بالنفس؟","title":"ما أفضل أنواع الجهاد؟","answer":"الجواب: الواجب الجهادان: جهاد النفس عن المعاصي، وجهاد الأعداء بالمال والنفس، لكن إذا لم يحصل هذا فجهاد الكفار بالنفس والمال أعظم من جهاد النفس بالمعاصي. وجهاد الكفار من أسباب هداية الله له، وتوفيق الله له، حتى يدع المعاصي؛ لأنَّ المعاصي مما يُعين الأعداء، ومما يُسبب ضعف النفس عن الجهاد، فإذا منَّ الله عليه بترك المعاصي صار هذا أعظم في الجهاد، وأكبر في الجهاد، وأنفع للجهاد.\nفجهاد الكفار مع المسلمين، والتعاون مع المسلمين -ولو كانت عنده معصية- أوجب، فليس من شرط المجاهد أن يكون تقيًّا نقيًّا، لا، يُجاهد ولو كانت عنده معاصٍ، يُجاهد مع  إخوانه بنفسه وماله، لكن إذا رزقه الله الجهادَ لنفسه في ترك المعاصي مع جهاد الكفار؛ كان هذا أكمل، وهو واجبٌ عليه، وفرضٌ عليه.\nفعليه أن يُجاهد هذا وهذا: أن يُجاهد النفس في ترك المعاصي، ويُجاهد أعداء الله بنفسه وماله وقلمه، فالجهاد بالقلم جهادٌ عظيمٌ، يقول النبيُّ ﷺ: جاهدوا المشركين بأموالكم، وأنفسكم، وألسنتكم رواه النسائي وأحمد وجماعة بإسنادٍ صحيحٍ.","link":"https://binbaz.org.sa/fatwas/2798/ما-افضل-انواع-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0271.mp3","categories":["الجهاد والسير"]},{"id":50,"question":"فضيلة الشيخ هنا سائل يسأل ويقول: هل الجهاد في هذا الزمان فرض كفاية أم فرض عين؟ وما الفرق بينهما، وما هي شروطهما؟","title":"هل الجهاد في هذا الزمان فرض عين؟","answer":"الجواب: الجهاد أصله فرض كفاية، هذا هو الأصل فإذا قام به من يكفي سقط عن الباقين، ولهذا كان النبي ﷺ يجاهد بنفسه ويرسل البعوث والسرايا وبقية المسلمين يقيمون في البلاد للمسائل الأخرى والحاجات الأخرى. وقد يتعين إذا استنفر الإمام من يصلح للجهاد؛ فيتعين عليه؛ لقوله ﷺ: وإذا استنفُرتم فانفروا، ويتعين أيضًا إذا هجم العدو على البلاد الإسلامية، يتعين على المسلمين أن يصدوه وأن يقاتلوه حتى ينقذوا البلاد منه، كما قد وقع في أفغانستان الآن، وهكذا في حال ثالثة وهي ما إذا كان الرجل في الصفين في صف المسلمين ضد عدوهم وقت قيام الجهاد واصطفاف المجاهدين لقتال عدوهم؛ فإنه ليس له أن يخذلهم وليس له أن ينحرف، بل عليه أن يجاهد مع إخوانه ويلتزم. وما سوى ذلك فهو سُنة ومن أفضل الأعمال، بل هو أفضل عمل يتطوع به الإنسان، الجهاد؛ لأنه جاء فيه من النصوص ما لم يأت بغيره في فضل الجهاد.","link":"https://binbaz.org.sa/fatwas/2961/هل-الجهاد-في-هذا-الزمان-فرض-عين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0024.mp3","categories":["الجهاد والسير"]},{"id":97,"question":"يقول هذا السَّائل: ما حكم مَن تخاذل في الدِّفاع عن راية الإسلام والدفاع عن الوطن؟ هل يُعتبر كافرًا أو مُرتدًّا؟","title":"حكم من يتخاذل في الدفاع عن الدين والوطن","answer":"الجواب: لا،ـ يكون عاصيًا، إذا تأخَّر يكون عاصيًا؛ لأن الواجب عليه أن يُشارك، فالله يقول: وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ [الأنفال:60]، ويقول: خُذُوا حِذْرَكُمْ [النساء:71]، ويقول النبيُّ ﷺ: وإذا استُنْفِرْتُم فانفروا، ويقول الربُّ جلَّ وعلا: إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا [التوبة:39].\nفالواجب إذا دعت الحاجةُ إلى هذا أن ينفر، وأن يستجيب لداعي النَّفير من جهة الدولة التي فيها ضد المُغْتَصِب، وضد الظالم، وضد العدو، فإذا تأخَّر وجبن؛ صار عاصيًا بذلك، ولا يكون كافرًا.","link":"https://binbaz.org.sa/fatwas/3126/حكم-من-يتخاذل-في-الدفاع-عن-الدين-والوطن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0077.mp3","categories":["الجهاد والسير"]},{"id":102,"question":"يقول هذا السائل: أرجو من سماحتكم توضيح بعض النقاط الآتية:أولًا: استدلَّ مجلسُ الإفتاء الأعلى بحضور سماحتكم بشأن تواجد القوات الأمريكية بحديث عبدالله بن أُرَيْقِط الذي استعان به الرسولُ ﷺ كدليلٍ إلى المدينة، وقد سمعتُ من أحد المشايخ أن الاستدلال خاطئ؛ لأنه يُعتبر من الاستئجار، وليس من باب الاستعانة به ضدّ المسلمين، أو ضدّ الكافرين، أرجو التَّوضيح، وجزاكم الله خيرًا.","title":"ما الجائز والممنوع في الاستعانة بالمشركين؟","answer":"الجواب: هذا غلطٌ، هو استعانة ولو ما استأجره، هو استعان بكافرٍ حتى يدل على الطريق المُناسب إلى المدينة، فالاستعانة إنما تكون إذا دعت الحاجةُ إليها، سواء بأجرٍ أو بغير أجرٍ، فالذي قال أنه إجارة وجوَّزه من أجل الإجارة قد غلط، فالاستعانة بالمشركين إذا جازت بالإجارة جازت بغير الإجارة من باب أولى، فالاستعانة بهم في مصلحة المسلمين مع أمن الخطر جائزة، بأجرٍ أو بغير أجرٍ، فلو قال: تُعينني على صدِّ هذا الصَّائل ولك مئة ريـال، فهذا جائز، ولو أعانه بدون شيءٍ جاز.\nوكونه استأجره بدراهم ما يمنع الإعانة، فكونهم يُقاتلون معنا ويُعْطَون شيئًا -يُرْضَخ لهم- مساعدةً لهم على مساعدتهم لنا؛ لا بأس بهذا، فهي استعانة ولو أعطاه أجرة؛ لأنه استعان به حتى يدله على الطريق.\nوهكذا كونه ﷺ يَعْرِض نفسه على مجتمعات الكفار في مِنى: مَن يُجيره حتى يُبَلِّغ رسالة ربِّه، فهذه استعانة بهم، فلم يقبل هذا إلَّا الأنصار رضي الله عنهم وأرضاهم، واستجار بجماعةٍ فأبوا ولم يقبل إلَّا المطعم بن عدي، فأجاره وحمل السلاح حتى حماه من شرِّ الأعداء، وأقرُّوا جواره، وهذه الاستعانة كانت قبل بدر.\nوهكذا بعد بدرٍ استعان بدروع من صفوان بن أمية يوم حنين، واستعان باليهود في خيبر سنة سبعٍ من الهجرة، وجعل إليهم أموال المسلمين: يعمرون النَّخيل والزروع بالنصف في مصلحة المسلمين، وهم يهود، فاستعان بهم في مصلحة المسلمين بالنصف.\nفالاستعانة بأجرٍ أو بغير أجرٍ جائزة إذا دعت الحاجةُ إليها والمصلحة، عند الضَّرورة، وعند الحاجة الشَّديدة، وإذا أغنى اللهُ عنهم لم تَجُز الاستعانة بهم.\nوالنبي ﷺ حين ردَّ بعض المشركين يوم بدر؛ كان ذلك لأنه ﷺ ما كان في حاجةٍ إليهم، فردَّهم لأسبابٍ، واستعان بهم لأسبابٍ.\nوالأحاديث ما يُضرب بعضُها ببعضٍ، بل يجب أن يُجمع بينها، ويُوفَّق بينها، ويُحتج بها جميعًا، فإذا دعت الحاجةُ أو الضَّرورة استُعين بهم، وإذا لم تدع الحاجةُ فلا، كما فعل النبيُّ ﷺ يوم بدر حين ردَّ المشركين وقال: لا نستعين بمُشْرِكٍ، وهو ﷺ استعان بالمُشرك في قدومه من الطَّائف، وفي ذهابه إلى المدينة بطريق عبدالله بن أُريقط، فكل هذه استعانة، سواء كانت بأجرةٍ أو بغير أجرةٍ.\nفإذا قلنا مثلًا للكافر المُعَيَّن: ساعدنا على محاربة صدام، وأعنا على صدام، ونُعطيك كذا وكذا كل يوم؟ فهذه استعانة بأجرٍ، وإذا قال: لا، ما أبغي أجرًا، فهو من باب أوْلى، ومن الغلط القول بأنَّ هذه الدَّعوى إجارة، هي إجارة، لكنها استعانة مع أنها إجارة، وهكذا فعل المسلمون عند الحاجة.\nفإذا دعت الحاجةُ والضَّرورة وجب دفع الشر بالممكن، سواء كان بمسلمٍ أو كافرٍ أو عاصٍ أو منافق عند الضَّرورة، بشرط مراعاة السلامة، وأن الغالب السلامة والنفع بهذا المُستعان به ضدّ العدو المُستعان عليه.\nوبعض الأئمَّة قال: إن الاستعانة بالمُشرك منسوخة، قاله الشافعي وجماعة، قالوا: إنها منسوخة، وأنَّ النبي ﷺ استعان بهم بعد ذلك.\nوقال آخرون: لا، ليس بنسخٍ، ولكن هذا في محلِّه، وهذا في محلِّه، وهو الصواب، فالصواب عدم النسخ؛ لأنه لا دليلَ على النسخ، والجمع بين النصوص أوْلى من النسخ، فيجوز عند الحاجة، ولا يجوز عند عدم الحاجة، وهذا هو الجمع بين الأحاديث وبين كلام أهل العلم رحمهم الله.","link":"https://binbaz.org.sa/fatwas/3197/ما-الجاىز-والممنوع-في-الاستعانة-بالمشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0083.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":102,"question":"يقول هذا السائل: أرجو من سماحتكم توضيح بعض النقاط الآتية:أولًا: استدلَّ مجلسُ الإفتاء الأعلى بحضور سماحتكم بشأن تواجد القوات الأمريكية بحديث عبدالله بن أُرَيْقِط الذي استعان به الرسولُ ﷺ كدليلٍ إلى المدينة، وقد سمعتُ من أحد المشايخ أن الاستدلال خاطئ؛ لأنه يُعتبر من الاستئجار، وليس من باب الاستعانة به ضدّ المسلمين، أو ضدّ الكافرين، أرجو التَّوضيح، وجزاكم الله خيرًا.","title":"ما الجائز والممنوع في الاستعانة بالمشركين؟","answer":"الجواب: هذا غلطٌ، هو استعانة ولو ما استأجره، هو استعان بكافرٍ حتى يدل على الطريق المُناسب إلى المدينة، فالاستعانة إنما تكون إذا دعت الحاجةُ إليها، سواء بأجرٍ أو بغير أجرٍ، فالذي قال أنه إجارة وجوَّزه من أجل الإجارة قد غلط، فالاستعانة بالمشركين إذا جازت بالإجارة جازت بغير الإجارة من باب أولى، فالاستعانة بهم في مصلحة المسلمين مع أمن الخطر جائزة، بأجرٍ أو بغير أجرٍ، فلو قال: تُعينني على صدِّ هذا الصَّائل ولك مئة ريـال، فهذا جائز، ولو أعانه بدون شيءٍ جاز.\nوكونه استأجره بدراهم ما يمنع الإعانة، فكونهم يُقاتلون معنا ويُعْطَون شيئًا -يُرْضَخ لهم- مساعدةً لهم على مساعدتهم لنا؛ لا بأس بهذا، فهي استعانة ولو أعطاه أجرة؛ لأنه استعان به حتى يدله على الطريق.\nوهكذا كونه ﷺ يَعْرِض نفسه على مجتمعات الكفار في مِنى: مَن يُجيره حتى يُبَلِّغ رسالة ربِّه، فهذه استعانة بهم، فلم يقبل هذا إلَّا الأنصار رضي الله عنهم وأرضاهم، واستجار بجماعةٍ فأبوا ولم يقبل إلَّا المطعم بن عدي، فأجاره وحمل السلاح حتى حماه من شرِّ الأعداء، وأقرُّوا جواره، وهذه الاستعانة كانت قبل بدر.\nوهكذا بعد بدرٍ استعان بدروع من صفوان بن أمية يوم حنين، واستعان باليهود في خيبر سنة سبعٍ من الهجرة، وجعل إليهم أموال المسلمين: يعمرون النَّخيل والزروع بالنصف في مصلحة المسلمين، وهم يهود، فاستعان بهم في مصلحة المسلمين بالنصف.\nفالاستعانة بأجرٍ أو بغير أجرٍ جائزة إذا دعت الحاجةُ إليها والمصلحة، عند الضَّرورة، وعند الحاجة الشَّديدة، وإذا أغنى اللهُ عنهم لم تَجُز الاستعانة بهم.\nوالنبي ﷺ حين ردَّ بعض المشركين يوم بدر؛ كان ذلك لأنه ﷺ ما كان في حاجةٍ إليهم، فردَّهم لأسبابٍ، واستعان بهم لأسبابٍ.\nوالأحاديث ما يُضرب بعضُها ببعضٍ، بل يجب أن يُجمع بينها، ويُوفَّق بينها، ويُحتج بها جميعًا، فإذا دعت الحاجةُ أو الضَّرورة استُعين بهم، وإذا لم تدع الحاجةُ فلا، كما فعل النبيُّ ﷺ يوم بدر حين ردَّ المشركين وقال: لا نستعين بمُشْرِكٍ، وهو ﷺ استعان بالمُشرك في قدومه من الطَّائف، وفي ذهابه إلى المدينة بطريق عبدالله بن أُريقط، فكل هذه استعانة، سواء كانت بأجرةٍ أو بغير أجرةٍ.\nفإذا قلنا مثلًا للكافر المُعَيَّن: ساعدنا على محاربة صدام، وأعنا على صدام، ونُعطيك كذا وكذا كل يوم؟ فهذه استعانة بأجرٍ، وإذا قال: لا، ما أبغي أجرًا، فهو من باب أوْلى، ومن الغلط القول بأنَّ هذه الدَّعوى إجارة، هي إجارة، لكنها استعانة مع أنها إجارة، وهكذا فعل المسلمون عند الحاجة.\nفإذا دعت الحاجةُ والضَّرورة وجب دفع الشر بالممكن، سواء كان بمسلمٍ أو كافرٍ أو عاصٍ أو منافق عند الضَّرورة، بشرط مراعاة السلامة، وأن الغالب السلامة والنفع بهذا المُستعان به ضدّ العدو المُستعان عليه.\nوبعض الأئمَّة قال: إن الاستعانة بالمُشرك منسوخة، قاله الشافعي وجماعة، قالوا: إنها منسوخة، وأنَّ النبي ﷺ استعان بهم بعد ذلك.\nوقال آخرون: لا، ليس بنسخٍ، ولكن هذا في محلِّه، وهذا في محلِّه، وهو الصواب، فالصواب عدم النسخ؛ لأنه لا دليلَ على النسخ، والجمع بين النصوص أوْلى من النسخ، فيجوز عند الحاجة، ولا يجوز عند عدم الحاجة، وهذا هو الجمع بين الأحاديث وبين كلام أهل العلم رحمهم الله.","link":"https://binbaz.org.sa/fatwas/3197/ما-الجاىز-والممنوع-في-الاستعانة-بالمشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0083.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":275,"question":"ما حكم مَن ذهب للجهاد من دون علم والديه، واستشهد رحمه الله، هل يدخل في حكم المُجاهد في سبيل الله؟","title":"حكم من ذهب للجهاد دون علم والديه واستشهد","answer":"الجواب: نرجو له ذلك إن شاء الله، نرجو له ذلك، نرجو له أن يكون شهيدًا مغفورًا له؛ لأنَّ ذهابه بغير إذن والديه عن اجتهادٍ وعن رغبةٍ في الخير، واستئذان الوالدين فيه من الإشكال ما فيه في مثل هذا، فنرجو له الخير العظيم.","link":"https://binbaz.org.sa/fatwas/4272/حكم-من-ذهب-للجهاد-دون-علم-والديه-واستشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0320.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":735,"question":"أنا أحبُّ الجهاد في سبيل الله، ولكني لا أستطيع أن أُجاهد بنفسي، فهل يكفي الجهاد بالمال؟ وهل فضله مثل فضل الجهاد بالنَّفس؟","title":"هل الجهاد بالمال يَعْدِل الجهاد بالنفس؟","answer":"الجواب: كل مسلم يُحبُّ الجهاد في سبيل الله، ما هو أنت وحدك، كل مسلمٍ يُحبُّ الجهاد في سبيل الله، والجهاد في سبيل الله من أفضل القُربات، وأعظم الطَّاعات، كما قالت عائشة رضي الله عنها: يا رسول الله، نجد الجهادَ أفضل الأعمال، أفلا نُجاهد؟ قال عليه الصلاة والسلام: عليكنَّ جهادٌ لا قتالَ فيه: الحج والعمرة، وقال الله جلَّ وعلا في كتابه العظيم: يَا أَيُّهَا الَّذِينَ آمَنُوا هَلْ أَدُلُّكُمْ عَلَى تِجَارَةٍ تُنْجِيكُمْ مِنْ عَذَابٍ أَلِيمٍ ۝ تُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِ وَتُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ ذَلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ [الصف:10- 11]، وقال تعالى: انْفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ فِي سَبِيلِ اللَّهِ ذَلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ [التوبة:41].\nفالجهاد في سبيل الله يكون بالمال، ويكون بالنفس، والجهاد بالمال أنفع وأكثر، والجهاد بالنفس أغلى وأشرف، ولهذا قدَّم الله الجهاد بالمال فقال: انْفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ فِي سَبِيلِ اللَّهِ وفي آياتٍ كثيرات، وذكر النَّفس أولًا في آيةٍ واحدةٍ فقال تعالى: إِنَّ اللَّهَ اشْتَرَى مِنَ الْمُؤْمِنِينَ أَنْفُسَهُمْ وَأَمْوَالَهُمْ بِأَنَّ لَهُمُ الْجَنَّةَ [التوبة:111].\nفالجهاد بالنفس أعلى ما عند الإنسان، جهاده بنفسه، ثم الجهاد بالمال، لكن قدَّم الله المال في مواضع كثيرة لأنه أعمّ نفعًا، فبالمال يُشترى السلاح، وبالمال يُشترى الطعام، وبالمال يُستأجر المجاهدون والجنود، وبالمال تُحصّن الثُّغور، وبالمال يُستأجر مَن ينفع المسلمين في حمل حاجاتهم.\nفالمال له جهات كبيرة، ولكن بالنفس -أي: أن الشخص المعين كونه يطيب بنفسه ويُقدِّم نفسه- هذا أفضل من المال، وإذا لم يستطع جاهد بالمال، فإن استطاع بهما جميعًا؛ جاهد بهما جميعًا.","link":"https://binbaz.org.sa/fatwas/20606/هل-الجهاد-بالمال-يعدل-الجهاد-بالنفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0544فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":735,"question":"أنا أحبُّ الجهاد في سبيل الله، ولكني لا أستطيع أن أُجاهد بنفسي، فهل يكفي الجهاد بالمال؟ وهل فضله مثل فضل الجهاد بالنَّفس؟","title":"هل الجهاد بالمال يَعْدِل الجهاد بالنفس؟","answer":"الجواب: كل مسلم يُحبُّ الجهاد في سبيل الله، ما هو أنت وحدك، كل مسلمٍ يُحبُّ الجهاد في سبيل الله، والجهاد في سبيل الله من أفضل القُربات، وأعظم الطَّاعات، كما قالت عائشة رضي الله عنها: يا رسول الله، نجد الجهادَ أفضل الأعمال، أفلا نُجاهد؟ قال عليه الصلاة والسلام: عليكنَّ جهادٌ لا قتالَ فيه: الحج والعمرة، وقال الله جلَّ وعلا في كتابه العظيم: يَا أَيُّهَا الَّذِينَ آمَنُوا هَلْ أَدُلُّكُمْ عَلَى تِجَارَةٍ تُنْجِيكُمْ مِنْ عَذَابٍ أَلِيمٍ ۝ تُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِ وَتُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ ذَلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ [الصف:10- 11]، وقال تعالى: انْفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ فِي سَبِيلِ اللَّهِ ذَلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ [التوبة:41].\nفالجهاد في سبيل الله يكون بالمال، ويكون بالنفس، والجهاد بالمال أنفع وأكثر، والجهاد بالنفس أغلى وأشرف، ولهذا قدَّم الله الجهاد بالمال فقال: انْفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ فِي سَبِيلِ اللَّهِ وفي آياتٍ كثيرات، وذكر النَّفس أولًا في آيةٍ واحدةٍ فقال تعالى: إِنَّ اللَّهَ اشْتَرَى مِنَ الْمُؤْمِنِينَ أَنْفُسَهُمْ وَأَمْوَالَهُمْ بِأَنَّ لَهُمُ الْجَنَّةَ [التوبة:111].\nفالجهاد بالنفس أعلى ما عند الإنسان، جهاده بنفسه، ثم الجهاد بالمال، لكن قدَّم الله المال في مواضع كثيرة لأنه أعمّ نفعًا، فبالمال يُشترى السلاح، وبالمال يُشترى الطعام، وبالمال يُستأجر المجاهدون والجنود، وبالمال تُحصّن الثُّغور، وبالمال يُستأجر مَن ينفع المسلمين في حمل حاجاتهم.\nفالمال له جهات كبيرة، ولكن بالنفس -أي: أن الشخص المعين كونه يطيب بنفسه ويُقدِّم نفسه- هذا أفضل من المال، وإذا لم يستطع جاهد بالمال، فإن استطاع بهما جميعًا؛ جاهد بهما جميعًا.","link":"https://binbaz.org.sa/fatwas/20606/هل-الجهاد-بالمال-يعدل-الجهاد-بالنفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0544فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":1272,"question":"أرجو من سماحتكم توضيح بعض النقاط التالية:أولًا: استدلَّ مجلس الإفتاء الأعلى بحضور سماحتكم بشأن تواجد القوات الأمريكية بحديث عبدالله بن أريقط الذي استعان به الرسولُ ﷺ كدليلٍ إلى المدينة، وقد سمعتُ من أحد المشايخ أن الاستدلال خاطئٌ؛ لأنه يُعتبر من الاستئجار، وليس من باب الاستعانة به ضدّ المُسلمين -أو ضد الكافرين لعله- أرجو التوضيح، جزاكم الله خيرًا.","title":"حكم الاستعانة بالكفار في مصلحة المسلمين","answer":"الجواب:\nهذا غلطٌ، هو استعانة ولو ما استأجره، هو استعانة بكافرٍ حتى يدله على الطريق المناسب إلى المدينة، فالاستعانة إذا دعت الحاجةُ إليها، سواء بأجرٍ أو بغير أجرٍ، فالذي قال: إنه إجارة، وجوَّزه من أجل الإجارة، هذا غلطٌ، الاستعانة بالمشركين إذا جازت في الإجارة جازت بغير الإجارة من باب أوْلى، فالاستعانة بهم في مصلحة المسلمين مع أمن الخطر هذا جائز، بأجرٍ أو بغير أجرٍ، لو قال: تُعينني على هذا الأمر -على صدِّ هذا الصائل- ولك مئة ريـال جائز، ولو أعانه بدون شيءٍ جائز.\nفهذا كونه استأجره بدراهم لا يمنع الإعانة، وكونهم يُقاتلون معنا ويُعطون -يُرْضَخ لهم شيء- مساعدةً لهم على مُساعدتهم لنا لا بأس بهذا، هي استعانة، ولو أعطاه أجرةً؛ لأنه استعان به حتى يدله على الطريق.\nوهكذا كونه ﷺ يعرض نفسَه على مجتمعات الكفار في مِنى ليُجيروه حتى يُبلِّغ رسالة ربه، هذه استعانة بهم، فلم يقبل هذا إلا الأنصار  وأرضاهم، واستجار بجماعةٍ فأبوا، فلم يقبل إلا المطعم بن عدي، فأجاره وحمل السلاح حتى حماه من شرِّ الأعداء، ونفذوا جواره، وهذه استعانة قبل بدر، وهكذا بعد بدر استعان بدروع من صفوان بن أمية يوم حنين، واستعان باليهود في خيبر سنة سبعٍ من الهجرة، وجعل إليهم أموال المسلمين: يعمرون النَّخيل والزروع بالنصف في مصلحة المسلمين، وهم يهود، استعان بهم في مصلحة المسلمين بالنصف.\nفالاستعانة بأجرٍ أو بغير أجرٍ جائزة إذا دعت الحاجةُ إليها والمصلحة، عند الضَّرورة، وعند الحاجة الشديدة.  وإذا أغنى الله عنهم؛ لم تجز الاستعانةُ بهم، والنبي ﷺ حين ردَّ بعض المشركين يوم بدرٍ لأنه صلى الله عليه وسلم ما كان في حاجةٍ إليه، فردَّه لأسبابٍ، واستعان بهم لأسبابٍ.\nوالأحاديث ما يُضرب بعضُها ببعض، الأحاديث يجب أن يُجمع بينها، ويُوفَّق بينها، ويُحتج بها جميعًا، فإذا دعت الحاجةُ أو الضَّرورة استُعين به، وإذا لم تدع الحاجةُ كما فعل النبيُّ يوم بدر حين ردَّه وقال: لا نستعين بمُشْرِكٍ، يرده.\nوهو ﷺ استعان بالمشرك في قدومه من الطائف، وفي ذهابه إلى المدينة من طريق عبدالله بن أُريقط، كلها استعانة، سواء بأجرةٍ أو بغير أجرةٍ، فإذا قلنا لهم -مثلًا للكافر المعين- ساعدنا على محاربة صَدَّام، وأعنا على صدام، ونُعطيك كذا وكذا كل يومٍ، هذه استعانة بأجرٍ، وإذا قال: لا أريد أجرًا؛ فمن باب أوْلى.\nهذا غلطٌ في الدعوى: أنها إجارة، هي إجارة، لكنها استعانة مع أنها إجارة، وهكذا فعل المسلمون عند الحاجة، إذا دعت الحاجةُ والضَّرورة وجب دفع الشرِّ بالممكن، سواء كان بمسلمٍ أو كافرٍ أو عاصٍ أو منافقٍ عند الضَّرورة، بشرط مراعاة السلامة، وأن الغالب السلامة والنفع بهذا المستعان به ضد العدو المستعان عليه.\nبعض الأئمَّة قال: إن الاستعانة بالمشرك منسوخة، كما قال الشافعي وجماعة، قالوا: إنها منسوخة، وأن النبي استعان بهم بعد ذلك.\nوقال آخرون: لا، ليس بنسخٍ، ولكن هذا في محلِّه، وهذا في محله، وهو الصواب.\nالصواب عدم النسخ؛ لأنه لا دليلَ على النسخ، والجمع بين النصوص أوْلى من النسخ، فيجوز عند الحاجة، ولا يجوز عند عدم الحاجة، وهذا الجمع بين الأحاديث وبين كلام أهل العلم رحمهم الله.","link":"https://binbaz.org.sa/fatwas/21333/حكم-الاستعانة-بالكفار-في-مصلحة-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1076ما حكم الأستعانة بالكفار في مصلحة المسلمين مع أمن الخطر؟ ابن باز.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":1272,"question":"أرجو من سماحتكم توضيح بعض النقاط التالية:أولًا: استدلَّ مجلس الإفتاء الأعلى بحضور سماحتكم بشأن تواجد القوات الأمريكية بحديث عبدالله بن أريقط الذي استعان به الرسولُ ﷺ كدليلٍ إلى المدينة، وقد سمعتُ من أحد المشايخ أن الاستدلال خاطئٌ؛ لأنه يُعتبر من الاستئجار، وليس من باب الاستعانة به ضدّ المُسلمين -أو ضد الكافرين لعله- أرجو التوضيح، جزاكم الله خيرًا.","title":"حكم الاستعانة بالكفار في مصلحة المسلمين","answer":"الجواب:\nهذا غلطٌ، هو استعانة ولو ما استأجره، هو استعانة بكافرٍ حتى يدله على الطريق المناسب إلى المدينة، فالاستعانة إذا دعت الحاجةُ إليها، سواء بأجرٍ أو بغير أجرٍ، فالذي قال: إنه إجارة، وجوَّزه من أجل الإجارة، هذا غلطٌ، الاستعانة بالمشركين إذا جازت في الإجارة جازت بغير الإجارة من باب أوْلى، فالاستعانة بهم في مصلحة المسلمين مع أمن الخطر هذا جائز، بأجرٍ أو بغير أجرٍ، لو قال: تُعينني على هذا الأمر -على صدِّ هذا الصائل- ولك مئة ريـال جائز، ولو أعانه بدون شيءٍ جائز.\nفهذا كونه استأجره بدراهم لا يمنع الإعانة، وكونهم يُقاتلون معنا ويُعطون -يُرْضَخ لهم شيء- مساعدةً لهم على مُساعدتهم لنا لا بأس بهذا، هي استعانة، ولو أعطاه أجرةً؛ لأنه استعان به حتى يدله على الطريق.\nوهكذا كونه ﷺ يعرض نفسَه على مجتمعات الكفار في مِنى ليُجيروه حتى يُبلِّغ رسالة ربه، هذه استعانة بهم، فلم يقبل هذا إلا الأنصار  وأرضاهم، واستجار بجماعةٍ فأبوا، فلم يقبل إلا المطعم بن عدي، فأجاره وحمل السلاح حتى حماه من شرِّ الأعداء، ونفذوا جواره، وهذه استعانة قبل بدر، وهكذا بعد بدر استعان بدروع من صفوان بن أمية يوم حنين، واستعان باليهود في خيبر سنة سبعٍ من الهجرة، وجعل إليهم أموال المسلمين: يعمرون النَّخيل والزروع بالنصف في مصلحة المسلمين، وهم يهود، استعان بهم في مصلحة المسلمين بالنصف.\nفالاستعانة بأجرٍ أو بغير أجرٍ جائزة إذا دعت الحاجةُ إليها والمصلحة، عند الضَّرورة، وعند الحاجة الشديدة.  وإذا أغنى الله عنهم؛ لم تجز الاستعانةُ بهم، والنبي ﷺ حين ردَّ بعض المشركين يوم بدرٍ لأنه صلى الله عليه وسلم ما كان في حاجةٍ إليه، فردَّه لأسبابٍ، واستعان بهم لأسبابٍ.\nوالأحاديث ما يُضرب بعضُها ببعض، الأحاديث يجب أن يُجمع بينها، ويُوفَّق بينها، ويُحتج بها جميعًا، فإذا دعت الحاجةُ أو الضَّرورة استُعين به، وإذا لم تدع الحاجةُ كما فعل النبيُّ يوم بدر حين ردَّه وقال: لا نستعين بمُشْرِكٍ، يرده.\nوهو ﷺ استعان بالمشرك في قدومه من الطائف، وفي ذهابه إلى المدينة من طريق عبدالله بن أُريقط، كلها استعانة، سواء بأجرةٍ أو بغير أجرةٍ، فإذا قلنا لهم -مثلًا للكافر المعين- ساعدنا على محاربة صَدَّام، وأعنا على صدام، ونُعطيك كذا وكذا كل يومٍ، هذه استعانة بأجرٍ، وإذا قال: لا أريد أجرًا؛ فمن باب أوْلى.\nهذا غلطٌ في الدعوى: أنها إجارة، هي إجارة، لكنها استعانة مع أنها إجارة، وهكذا فعل المسلمون عند الحاجة، إذا دعت الحاجةُ والضَّرورة وجب دفع الشرِّ بالممكن، سواء كان بمسلمٍ أو كافرٍ أو عاصٍ أو منافقٍ عند الضَّرورة، بشرط مراعاة السلامة، وأن الغالب السلامة والنفع بهذا المستعان به ضد العدو المستعان عليه.\nبعض الأئمَّة قال: إن الاستعانة بالمشرك منسوخة، كما قال الشافعي وجماعة، قالوا: إنها منسوخة، وأن النبي استعان بهم بعد ذلك.\nوقال آخرون: لا، ليس بنسخٍ، ولكن هذا في محلِّه، وهذا في محله، وهو الصواب.\nالصواب عدم النسخ؛ لأنه لا دليلَ على النسخ، والجمع بين النصوص أوْلى من النسخ، فيجوز عند الحاجة، ولا يجوز عند عدم الحاجة، وهذا الجمع بين الأحاديث وبين كلام أهل العلم رحمهم الله.","link":"https://binbaz.org.sa/fatwas/21333/حكم-الاستعانة-بالكفار-في-مصلحة-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1076ما حكم الأستعانة بالكفار في مصلحة المسلمين مع أمن الخطر؟ ابن باز.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":1277,"question":"ما حكم مَن تخاذل في الدفاع عن راية الإسلام والدفاع عن الوطن؟ هل يُعتبر كافرًا أو مُرتدًّا؟","title":"حكم التخاذل في الدفاع عن الإسلام والوطن","answer":"الجواب:\nلا، يكون عاصيًا، إذا تأخَّر يكون عاصيًا؛ لأنَّ الواجب عليه أن يُشارك، الله يقول: وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ [الأنفال:60]، ويقول: خُذُوا حِذْرَكُمْ [النساء:71]، ويقول النبيُّ ﷺ: وإذا استُنفرتم فانفروا، ويقول الربُّ جل وعلا: إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا [التوبة:39].  فالواجب إذا دعت الحاجةُ إلى هذا أن ينْفِر، وأن يستجيب لداعي النَّفير من جهة الدولة التي فيها ضدّ المغتَصِب، وضد الظالم، وضد العدو، فإذا تأخَّر وجَبُن؛ صار عاصيًا بذلك، لا يكون كافرًا، يكون عاصيًا.","link":"https://binbaz.org.sa/fatwas/21328/حكم-التخاذل-في-الدفاع-عن-الاسلام-والوطن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1071ما حكم من تخاذل في الدفاع عن راية الإسلام والدفاع عن الوطن؟ ابن باز.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":1277,"question":"ما حكم مَن تخاذل في الدفاع عن راية الإسلام والدفاع عن الوطن؟ هل يُعتبر كافرًا أو مُرتدًّا؟","title":"حكم التخاذل في الدفاع عن الإسلام والوطن","answer":"الجواب:\nلا، يكون عاصيًا، إذا تأخَّر يكون عاصيًا؛ لأنَّ الواجب عليه أن يُشارك، الله يقول: وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ [الأنفال:60]، ويقول: خُذُوا حِذْرَكُمْ [النساء:71]، ويقول النبيُّ ﷺ: وإذا استُنفرتم فانفروا، ويقول الربُّ جل وعلا: إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا [التوبة:39].  فالواجب إذا دعت الحاجةُ إلى هذا أن ينْفِر، وأن يستجيب لداعي النَّفير من جهة الدولة التي فيها ضدّ المغتَصِب، وضد الظالم، وضد العدو، فإذا تأخَّر وجَبُن؛ صار عاصيًا بذلك، لا يكون كافرًا، يكون عاصيًا.","link":"https://binbaz.org.sa/fatwas/21328/حكم-التخاذل-في-الدفاع-عن-الاسلام-والوطن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1071ما حكم من تخاذل في الدفاع عن راية الإسلام والدفاع عن الوطن؟ ابن باز.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":1311,"question":"إنني أُحب الجهادَ، وقد امتزج حبُّه في قلبي، ولا أستطيع أن أصبر عنه، وقد استأذنتُ والدتي ولم تُوافق، ولكن تأثرت كثيرًا، ولا أستطيع أن أبتعد عن الجهاد، سماحة الشيخ، إنَّ أمنيتي في الحياة هي الجهاد في سبيل الله، وأن أُقتل في سبيله، وأمي لا تُوافق، دُلَّني جزاك الله خيرًا؟","title":"هل يجب استئذان الوالدين في الجهاد؟","answer":"الجواب:\nجهادك في أمك جهادٌ عظيمٌ، الزم أمك، وأحسن إليها، إلا إذا أمرك ولي الأمر بالجهاد فبادر، قال النبيُّ ﷺ: إذا استُنفرتم فانفروا، وما دام ما طُلبت فأحسن لأمك، وارحمها، وبرها جهادٌ عظيمٌ قدَّمه النبيُّ ﷺ على الجهاد، قيل: يا رسول الله، أي الأعمال أفضل؟ قال: إيمان بالله ورسوله، قيل: ثم أي؟ قال: بر الوالدين، قيل: ثم أي؟ قال: الجهاد في سبيل الله، فقدَّم برَّهما على الجهاد.\nوجاءه رجلٌ يستأذنه قال: يا رسول الله، إني أحبُّ أن أُجاهد، قال: هل استأذنتَ والديك؟ قال: لا، قال: ارجع فاستأذنهما، وفي اللفظ الآخر قال: ففيهما فجاهد.\nفهذه الوالدة ارحمها وأحسن إليها حتى تسمح لك، وأما إذا نزل البلاءُ بك فدافع عن نفسك، ولا حول ولا قوة إلا بالله، أو أمرك وليُّ الأمر بالنَّفير تنفر، ولو بغير رضاهما، قال النبيُّ ﷺ: وإذا استنفرتم فانفروا، قال الله جلَّ وعلا: إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا [التوبة:39].","link":"https://binbaz.org.sa/fatwas/21358/هل-يجب-استىذان-الوالدين-في-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1101أريد الجهاد في سبيل الله وأمي غير موافقة فما الحكم؟ ابن باز فتاوى.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":1350,"question":"ما المقصود بـ\"العدو\" هل يُطلق على المسلم أم الكافر؟","title":"هل يُطلق لفظ \"العدو\" على غير الكافر؟","answer":"الجواب:\nالمقصود: جهاد الكفار، يعني العدو عند الإطلاق يعني: الكافر.\nس: ما يكون شخصٌ عادَى شخصًا؟\nج: لا، العدو الكفار، عند الإطلاق، هُمُ الْعَدُوُّ فَاحْذَرْهُمْ  [المنافقون: 4].\nس: ما يُطلق عليه: مَن يعاديك في الدين؟\nج: العدو عند الإطلاق: العدو الكافر، أما العداوة التي بين الناس هذه عداوة خاصة، قد تكون لشحناء، قد.. لأسباب أخرى؛ مواريث أو غيرها، هذه عداوة خاصة، أمرها أسهل.","link":"https://binbaz.org.sa/fatwas/21442/هل-يطلق-لفظ-العدو-على-غير-الكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في مجاهدة العدو.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":1350,"question":"ما المقصود بـ\"العدو\" هل يُطلق على المسلم أم الكافر؟","title":"هل يُطلق لفظ \"العدو\" على غير الكافر؟","answer":"الجواب:\nالمقصود: جهاد الكفار، يعني العدو عند الإطلاق يعني: الكافر.\nس: ما يكون شخصٌ عادَى شخصًا؟\nج: لا، العدو الكفار، عند الإطلاق، هُمُ الْعَدُوُّ فَاحْذَرْهُمْ  [المنافقون: 4].\nس: ما يُطلق عليه: مَن يعاديك في الدين؟\nج: العدو عند الإطلاق: العدو الكافر، أما العداوة التي بين الناس هذه عداوة خاصة، قد تكون لشحناء، قد.. لأسباب أخرى؛ مواريث أو غيرها، هذه عداوة خاصة، أمرها أسهل.","link":"https://binbaz.org.sa/fatwas/21442/هل-يطلق-لفظ-العدو-على-غير-الكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في مجاهدة العدو.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":1374,"question":"بالنسبة إذا التقى المسلمون كفارًا في الجهاد في الصف وعلم المسلمون أن الكفار أكثر منهم عدة وعتادًا فرجعوا، هل هذا يعتبر فرارًا؟","title":"ما حكم الفرار من العدو لكثرة عُدَّته وعتاده؟","answer":"الجواب:\nإذا كانوا أكثر مِن الضعفين فلا بأس، أما إن كانوا مثلهم مرتين أو أقل فليس لهم الرجوع، عليهم الصبر الآنَ خَفَّفَ اللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا فَإِنْ يَكُنْ مِنْكُمْ مِائَةٌ صَابِرَةٌ يَغْلِبُوا مِائَتَيْنِ وَإِنْ يَكُنْ مِنْكُمْ أَلْفٌ يَغْلِبُوا أَلْفَيْنِ بِإِذْنِ اللَّهِ وَاللَّهُ مَعَ الصَّابِرِينَ [الأنفال:66] فإذا كانوا ضعفهم فالواجب المصابرة، وإن كانوا أكثر من الضعف يعني ثلاثة فأكثر؛ جاز لهم التَّحَيُّز والتأخر.","link":"https://binbaz.org.sa/fatwas/21467/ما-حكم-الفرار-من-العدو-لكثرة-عدته-وعتاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذ علم المجاهدون أن العدو أكثر عدة وعتاداً فرجعوا فهل هذا يعتبر فرارًا.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":1374,"question":"بالنسبة إذا التقى المسلمون كفارًا في الجهاد في الصف وعلم المسلمون أن الكفار أكثر منهم عدة وعتادًا فرجعوا، هل هذا يعتبر فرارًا؟","title":"ما حكم الفرار من العدو لكثرة عُدَّته وعتاده؟","answer":"الجواب:\nإذا كانوا أكثر مِن الضعفين فلا بأس، أما إن كانوا مثلهم مرتين أو أقل فليس لهم الرجوع، عليهم الصبر الآنَ خَفَّفَ اللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا فَإِنْ يَكُنْ مِنْكُمْ مِائَةٌ صَابِرَةٌ يَغْلِبُوا مِائَتَيْنِ وَإِنْ يَكُنْ مِنْكُمْ أَلْفٌ يَغْلِبُوا أَلْفَيْنِ بِإِذْنِ اللَّهِ وَاللَّهُ مَعَ الصَّابِرِينَ [الأنفال:66] فإذا كانوا ضعفهم فالواجب المصابرة، وإن كانوا أكثر من الضعف يعني ثلاثة فأكثر؛ جاز لهم التَّحَيُّز والتأخر.","link":"https://binbaz.org.sa/fatwas/21467/ما-حكم-الفرار-من-العدو-لكثرة-عدته-وعتاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذ علم المجاهدون أن العدو أكثر عدة وعتاداً فرجعوا فهل هذا يعتبر فرارًا.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":1616,"question":"إذا كان الشخص يريد الجهادَ فهل يستأذن والديه؟","title":"حكم استئذان الوالدين في الجهاد","answer":"الجواب:\nيستأذنهما، قال: ارجع فاستأذنهما، فإن أذنا لك وإلا فبرّهما، إلا إذا كان الجهاد واجبًا، مثل: حصر البلادَ عدوٌّ، أو كان بين الصَّفَّين، أو استنفره الإمامُ؛ فلا إذن، ففي هذه المواضع الثلاثة يجب عليه القتال ولا يستأذن.","link":"https://binbaz.org.sa/fatwas/21720/حكم-استىذان-الوالدين-في-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استئذان الوالدين في الجهاد.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":2301,"question":"إذا كان المسلمُ في الحرب وأُسِرَ، وطلبوا منه إفشاء السر، فهل الأفضل أن يكذب أو يُفشي السرَّ؟","title":"حكم إفشاء الأسير أسرار الحرب؟","answer":"الجواب:\nينظر الأصلح للمسلمين، والذي ما يضرّ المسلمين يفعله, فإذا كان إفشاءُ السرِّ يضرُّ المسلمين لا يُفشيه ولو قُتِلَ.","link":"https://binbaz.org.sa/fatwas/22425/حكم-افشاء-الاسير-اسرار-الحرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إفشاء الأسرار لأسير الحرب.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2301,"question":"إذا كان المسلمُ في الحرب وأُسِرَ، وطلبوا منه إفشاء السر، فهل الأفضل أن يكذب أو يُفشي السرَّ؟","title":"حكم إفشاء الأسير أسرار الحرب؟","answer":"الجواب:\nينظر الأصلح للمسلمين، والذي ما يضرّ المسلمين يفعله, فإذا كان إفشاءُ السرِّ يضرُّ المسلمين لا يُفشيه ولو قُتِلَ.","link":"https://binbaz.org.sa/fatwas/22425/حكم-افشاء-الاسير-اسرار-الحرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إفشاء الأسرار لأسير الحرب.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2370,"question":"في صحيح مسلم عن جابر بن سمرة وجابر بن عبدالله ومعاوية في وصف طائفة الحق أنهم يُقاتِلون، فهل القتال المقصود به ما يتبادر إلى الذهن من الحرب والسلاح أم غير ذلك؟","title":"معنى القتال في سبيل الله وكيفيته","answer":"الجواب:\nيقاتلون في سبيل الله يعني، يقاتلون في سبيل الله، يقاتلون في سبيل الله مَن خرج عن سبيل الله، الحرب هي الجهاد، الجهاد الشرعي.\nس: هل هذا يقوِّي الحديث الضعيف: الجهاد ماض مع كل بر وفاجر، على اعتبار أنه ماضٍ إلى يوم القيامة؟\nالشيخ: هو ماض بإجماع المسلمين، ماض إلى يوم القيامة، الجهاد ماض إلى يوم القيامة إذا وُجِدت أسبابه.\nس: وقوله \"عصابة\" يفيد جماعة، فهل معنى ذلك أنه لا يصح القتال إلا مع أمير؟\nالشيخ: لا بدّ أن يكون الجهاد خلف قائد شرعي، مع أمير شرعي، لا بدّ من قائد شرعي.","link":"https://binbaz.org.sa/fatwas/22495/معنى-القتال-في-سبيل-الله-وكيفيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجهاد في سبيل الله ماض إلى يوم القيامة.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2370,"question":"في صحيح مسلم عن جابر بن سمرة وجابر بن عبدالله ومعاوية في وصف طائفة الحق أنهم يُقاتِلون، فهل القتال المقصود به ما يتبادر إلى الذهن من الحرب والسلاح أم غير ذلك؟","title":"معنى القتال في سبيل الله وكيفيته","answer":"الجواب:\nيقاتلون في سبيل الله يعني، يقاتلون في سبيل الله، يقاتلون في سبيل الله مَن خرج عن سبيل الله، الحرب هي الجهاد، الجهاد الشرعي.\nس: هل هذا يقوِّي الحديث الضعيف: الجهاد ماض مع كل بر وفاجر، على اعتبار أنه ماضٍ إلى يوم القيامة؟\nالشيخ: هو ماض بإجماع المسلمين، ماض إلى يوم القيامة، الجهاد ماض إلى يوم القيامة إذا وُجِدت أسبابه.\nس: وقوله \"عصابة\" يفيد جماعة، فهل معنى ذلك أنه لا يصح القتال إلا مع أمير؟\nالشيخ: لا بدّ أن يكون الجهاد خلف قائد شرعي، مع أمير شرعي، لا بدّ من قائد شرعي.","link":"https://binbaz.org.sa/fatwas/22495/معنى-القتال-في-سبيل-الله-وكيفيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجهاد في سبيل الله ماض إلى يوم القيامة.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2707,"question":"مشاركة النساء بتضميد جراح القتال ما يُعَدُّ لهن جهادًا؟","title":"هل من الجهاد تضميد النساء لجراح القتال؟","answer":"الجواب: هذا إذا دَعَتْ له الحاجة، كما فُعل في عهد النبي ﷺ، يساعدن بقدر الطاقة مع التَّحَجُّب ومع الحذر مِن الخلوة، يعني مع مراعاة الحدود الشرعية، ويُرجى لهن فضل الجهاد إن شاء الله، لكن هذا جهاد خاص في مساعدة المجاهدين.","link":"https://binbaz.org.sa/fatwas/22849/هل-من-الجهاد-تضميد-النساء-لجراح-القتال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل جهاد النساء بتضميد جراح القتال.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2707,"question":"مشاركة النساء بتضميد جراح القتال ما يُعَدُّ لهن جهادًا؟","title":"هل من الجهاد تضميد النساء لجراح القتال؟","answer":"الجواب: هذا إذا دَعَتْ له الحاجة، كما فُعل في عهد النبي ﷺ، يساعدن بقدر الطاقة مع التَّحَجُّب ومع الحذر مِن الخلوة، يعني مع مراعاة الحدود الشرعية، ويُرجى لهن فضل الجهاد إن شاء الله، لكن هذا جهاد خاص في مساعدة المجاهدين.","link":"https://binbaz.org.sa/fatwas/22849/هل-من-الجهاد-تضميد-النساء-لجراح-القتال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل جهاد النساء بتضميد جراح القتال.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2726,"question":"يكفي المرء المسلم أن يقرأ أحاديث الجهاد والغزو حتى يسلم مِن هذا (وعيد حديثمن مات ولم يَغْزُ..) ؟","title":"كيف يُتجنّب وعيدُ \"من مات ولم يَغْزُ\"؟","answer":"الجواب: يقرأ حتى يستفيد؛ حتى تكون له نية صالحة لو قام الجهاد.\nس: حتى يسلم مما ورد...؟\nالشيخ: نعم، من مات ولم يغزُ ولم يحدّث نفسه بالغزو مات على شُعبة مِن النفاق.","link":"https://binbaz.org.sa/fatwas/22872/كيف-يتجنب-وعيد-من-مات-ولم-يغز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث من مات ولم يغزُ، ولم يحدث نفسه بالغزو.. هل تكفي قراءة أحاديث الجهاد.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":2730,"question":"الحراسة في غير وقت الحرب يكون لها هذا الفضل (الرِّباط)؟","title":"هل الحراسة في غير الحرب من الرِّباط؟","answer":"الجواب: نعم هذا رِباط، الحراسة هو الرِّباط، الرِّباط في سبيل الله في الثغور، في أطراف البلد، يُسمّى \"رِباط\".","link":"https://binbaz.org.sa/fatwas/22876/هل-الحراسة-في-غير-الحرب-من-الرباط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الرباط الحراسة في غير وقت الحرب.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2730,"question":"الحراسة في غير وقت الحرب يكون لها هذا الفضل (الرِّباط)؟","title":"هل الحراسة في غير الحرب من الرِّباط؟","answer":"الجواب: نعم هذا رِباط، الحراسة هو الرِّباط، الرِّباط في سبيل الله في الثغور، في أطراف البلد، يُسمّى \"رِباط\".","link":"https://binbaz.org.sa/fatwas/22876/هل-الحراسة-في-غير-الحرب-من-الرباط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الرباط الحراسة في غير وقت الحرب.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2731,"question":"إذا كان الجهاد فرض عين يجزئ عن الإنسان القيام بأهل المجاهد أو تجهيز المجاهدين؟","title":"هل يجزئ تجهيز المجاهد عن جهاد الفرض؟","answer":"الجواب: إذا دعت الحاجة نعم، لكن إذا دعت الحاجة إلى أنه يباشر باشر؛ لأنه قد تكون المسألة تدعو إلى جهاد بنفسه لهجوم العدو، لكن إذا تيسر أنه يقوم باللازم، ويجاهد أخوه أو عمه أو غيره أو جاره، ويكتفى بهذا؛ لا بأس، أما إن دعت الضرورة إلى أنه يباشر هو؛ لا يتخلف، يجاهد، حتى النساء يجاهدن.\nس: كذلك خلافة العالِم في قضاء أغراضه ومعاملاته؟\nالشيخ: هذا يدخل في حديث: من كان في حاجة أخيه كان الله في حاجته والله في عون العبد ما كان العبد في عون أخيه.\nس: ليست من هذا الباب؟\nالشيخ: لا. من باب التعاون على الخير.\nس: من باب مساعدة العالم...؟\nالشيخ: على حسب حال المُساعِد والمُساعَد، كل ما كان المساعَد أحوج وأنفع للمسلمين، والمساعِد يكون أكمل في الإخلاص والنية الصالحة؛ كان الأجر كذلك.","link":"https://binbaz.org.sa/fatwas/22879/هل-يجزى-تجهيز-المجاهد-عن-جهاد-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجزئ القيام بأهل المجاهدين وتجهيز المجاهدين عن جهاد الفرض.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2731,"question":"إذا كان الجهاد فرض عين يجزئ عن الإنسان القيام بأهل المجاهد أو تجهيز المجاهدين؟","title":"هل يجزئ تجهيز المجاهد عن جهاد الفرض؟","answer":"الجواب: إذا دعت الحاجة نعم، لكن إذا دعت الحاجة إلى أنه يباشر باشر؛ لأنه قد تكون المسألة تدعو إلى جهاد بنفسه لهجوم العدو، لكن إذا تيسر أنه يقوم باللازم، ويجاهد أخوه أو عمه أو غيره أو جاره، ويكتفى بهذا؛ لا بأس، أما إن دعت الضرورة إلى أنه يباشر هو؛ لا يتخلف، يجاهد، حتى النساء يجاهدن.\nس: كذلك خلافة العالِم في قضاء أغراضه ومعاملاته؟\nالشيخ: هذا يدخل في حديث: من كان في حاجة أخيه كان الله في حاجته والله في عون العبد ما كان العبد في عون أخيه.\nس: ليست من هذا الباب؟\nالشيخ: لا. من باب التعاون على الخير.\nس: من باب مساعدة العالم...؟\nالشيخ: على حسب حال المُساعِد والمُساعَد، كل ما كان المساعَد أحوج وأنفع للمسلمين، والمساعِد يكون أكمل في الإخلاص والنية الصالحة؛ كان الأجر كذلك.","link":"https://binbaz.org.sa/fatwas/22879/هل-يجزى-تجهيز-المجاهد-عن-جهاد-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجزئ القيام بأهل المجاهدين وتجهيز المجاهدين عن جهاد الفرض.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2732,"question":"هل ممكن أن يكون الجهاد فرض عين كالصيام كما قال تعالى: وَمَا كَانَ الْمُؤْمِنُونَ لِيَنْفِرُوا كَافَّةً فَلَوْلَا نَفَرَ مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ طَائِفَةٌ.. [التوبة:122]؟","title":"متى يكون الجهاد فرض عين أو فرض كفاية؟","answer":"الجواب: هذا فرض كفاية.\nس: هل يمكن أن يقع الجهاد كالصلاة والصيام؟\nالشيخ: كما بَيَّن العلماء، إذا كان في الصفين أو استنفرهم الإمام أو هجم عليهم العدو؛ يكون فرض عين.\nس: كالصلاة وكالصيام؟\nالشيخ: أيه، فرض عين مثل ما يهجم عليه العدو يدافع عن نفسه، فَرْضٌ عليه.","link":"https://binbaz.org.sa/fatwas/22880/متى-يكون-الجهاد-فرض-عين-او-فرض-كفاية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكون الجهاد فرض عين كالصيام ونحوه.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2732,"question":"هل ممكن أن يكون الجهاد فرض عين كالصيام كما قال تعالى: وَمَا كَانَ الْمُؤْمِنُونَ لِيَنْفِرُوا كَافَّةً فَلَوْلَا نَفَرَ مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ طَائِفَةٌ.. [التوبة:122]؟","title":"متى يكون الجهاد فرض عين أو فرض كفاية؟","answer":"الجواب: هذا فرض كفاية.\nس: هل يمكن أن يقع الجهاد كالصلاة والصيام؟\nالشيخ: كما بَيَّن العلماء، إذا كان في الصفين أو استنفرهم الإمام أو هجم عليهم العدو؛ يكون فرض عين.\nس: كالصلاة وكالصيام؟\nالشيخ: أيه، فرض عين مثل ما يهجم عليه العدو يدافع عن نفسه، فَرْضٌ عليه.","link":"https://binbaz.org.sa/fatwas/22880/متى-يكون-الجهاد-فرض-عين-او-فرض-كفاية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكون الجهاد فرض عين كالصيام ونحوه.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2739,"question":"يَحْرُم عليه أن يذهب للجهاد وعليه دَيْن؟","title":"ما حكم الذهاب للجهاد لمن عليه دَْين؟","answer":"الجواب: إذا كان يستطيع الوفاء يُوفِي، وإذا كان ما يستطيع يذهب للجهاد، ما يخالف، معذور.\nس: يكون الدَّيْن معلقًا عليه؟\nالشيخ: معلق، إن تيسر، وإلا ما هو بلزوم.","link":"https://binbaz.org.sa/fatwas/22887/ما-حكم-الذهاب-للجهاد-لمن-عليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجاهد من كان عليه دَين.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2739,"question":"يَحْرُم عليه أن يذهب للجهاد وعليه دَيْن؟","title":"ما حكم الذهاب للجهاد لمن عليه دَْين؟","answer":"الجواب: إذا كان يستطيع الوفاء يُوفِي، وإذا كان ما يستطيع يذهب للجهاد، ما يخالف، معذور.\nس: يكون الدَّيْن معلقًا عليه؟\nالشيخ: معلق، إن تيسر، وإلا ما هو بلزوم.","link":"https://binbaz.org.sa/fatwas/22887/ما-حكم-الذهاب-للجهاد-لمن-عليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجاهد من كان عليه دَين.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2742,"question":"متى يسأل الرجل عن راية الجهاد إذا شك في الجيش؟","title":"حكم السؤال عن راية الجيش عند الشك","answer":"الجواب: يجتهد، إذا رأى ظاهرهم الدعوة إلى الله والجهاد في سبيل الله فالحمد لله، ينظر ويسأل، عنده عقل وعنده سمع وعنده بصر، إذا كان مع قوم يجاهدون في سبيل الله لإعلاء دينه؛ هذا هو الجهاد في سبيل الله.","link":"https://binbaz.org.sa/fatwas/22890/حكم-السوال-عن-راية-الجيش-عند-الشك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السؤال عن راية الجهاد.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2742,"question":"متى يسأل الرجل عن راية الجهاد إذا شك في الجيش؟","title":"حكم السؤال عن راية الجيش عند الشك","answer":"الجواب: يجتهد، إذا رأى ظاهرهم الدعوة إلى الله والجهاد في سبيل الله فالحمد لله، ينظر ويسأل، عنده عقل وعنده سمع وعنده بصر، إذا كان مع قوم يجاهدون في سبيل الله لإعلاء دينه؛ هذا هو الجهاد في سبيل الله.","link":"https://binbaz.org.sa/fatwas/22890/حكم-السوال-عن-راية-الجيش-عند-الشك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السؤال عن راية الجهاد.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2753,"question":"متى يكون الجهاد فرض عين؟","title":"متى يكون الجهاد فرض عين؟","answer":"الجواب: في ثلاثة مواضع: عند هجوم العدو. وعند التقاء الصفين. وعند استنفار الإمام، إذا استنفره قال: فلان يمشي.  في ثلاثة مواضع إذا اسْتُنْفِرْتُمْ فَانْفِرُوا.","link":"https://binbaz.org.sa/fatwas/22901/متى-يكون-الجهاد-فرض-عين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون الجهاد فرض عين.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2753,"question":"متى يكون الجهاد فرض عين؟","title":"متى يكون الجهاد فرض عين؟","answer":"الجواب: في ثلاثة مواضع: عند هجوم العدو. وعند التقاء الصفين. وعند استنفار الإمام، إذا استنفره قال: فلان يمشي.  في ثلاثة مواضع إذا اسْتُنْفِرْتُمْ فَانْفِرُوا.","link":"https://binbaz.org.sa/fatwas/22901/متى-يكون-الجهاد-فرض-عين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون الجهاد فرض عين.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2793,"question":"بالنسبة للتمليك: كيف ضابطه من الناحية الشرعية؟","title":"ما أصل ملك اليمين وضابطه الشرعي؟","answer":"الجواب: أصله السَّبْي، ثم التوالد بعد ذلك والإرث والبيع والشراء، ولكن أصله السَّبْي من الكفار، عند الجهاد في سبيل الله يَسْبِي الأولاد والنساء والأسرى الذين يأسرهم المسلمون، قد يسترقونهم وقد يعتقونهم والحريم والولد يكونون أرقاء، ثم يتبايعهم الناس ويتوارثونهم الناس، هذا الأصل.\nس: في بعض البلدان فيها عبيد ورثها أكابر عن أكابر، هل هذا ممكن إنسان يشتريه ويعتقه؟\nالشيخ: ما في بأس، إذا شهد الشهود أنه مملوك ما في بأس.","link":"https://binbaz.org.sa/fatwas/22941/ما-اصل-ملك-اليمين-وضابطه-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أصل ملك اليمين كيف يكون.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2793,"question":"بالنسبة للتمليك: كيف ضابطه من الناحية الشرعية؟","title":"ما أصل ملك اليمين وضابطه الشرعي؟","answer":"الجواب: أصله السَّبْي، ثم التوالد بعد ذلك والإرث والبيع والشراء، ولكن أصله السَّبْي من الكفار، عند الجهاد في سبيل الله يَسْبِي الأولاد والنساء والأسرى الذين يأسرهم المسلمون، قد يسترقونهم وقد يعتقونهم والحريم والولد يكونون أرقاء، ثم يتبايعهم الناس ويتوارثونهم الناس، هذا الأصل.\nس: في بعض البلدان فيها عبيد ورثها أكابر عن أكابر، هل هذا ممكن إنسان يشتريه ويعتقه؟\nالشيخ: ما في بأس، إذا شهد الشهود أنه مملوك ما في بأس.","link":"https://binbaz.org.sa/fatwas/22941/ما-اصل-ملك-اليمين-وضابطه-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أصل ملك اليمين كيف يكون.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2841,"question":"إن كان الجهاد فرض عَيْن هل يُقَدَّم على بر الوالدين؟","title":"متى يُقَدَّم الجهادُ على بر الوالدين؟","answer":"الجواب: إذا كان فرض عين؛ قُدِّم على الجميع، مثل: هجم العدو على البلد، أو كان بين الصفين، أو استنفره الإمام؛ هذا فرض عين، في هذه الأحوال الثلاثة: إذا هجم العدو على البلد؛ وجب على الجميع الجهاد لدفعه حسب الطاقة.  أو استنفرهم الإمام؛ وجب عليهم الجهاد. أو حَضَر الصفين؛ لا ينحرف، لا يُوَلِّي الأدبار.","link":"https://binbaz.org.sa/fatwas/22991/متى-يقدم-الجهاد-على-بر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقدم جهاد الفرض العين على بر الوالدين.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2841,"question":"إن كان الجهاد فرض عَيْن هل يُقَدَّم على بر الوالدين؟","title":"متى يُقَدَّم الجهادُ على بر الوالدين؟","answer":"الجواب: إذا كان فرض عين؛ قُدِّم على الجميع، مثل: هجم العدو على البلد، أو كان بين الصفين، أو استنفره الإمام؛ هذا فرض عين، في هذه الأحوال الثلاثة: إذا هجم العدو على البلد؛ وجب على الجميع الجهاد لدفعه حسب الطاقة.  أو استنفرهم الإمام؛ وجب عليهم الجهاد. أو حَضَر الصفين؛ لا ينحرف، لا يُوَلِّي الأدبار.","link":"https://binbaz.org.sa/fatwas/22991/متى-يقدم-الجهاد-على-بر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقدم جهاد الفرض العين على بر الوالدين.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2846,"question":"أفضل العبادات البدنية الصلاة أو الجهاد؟","title":"هل أفضل العبادات البدنية: الصلاة أم الجهاد؟","answer":"الجواب: الجهاد أفضل، في التطوع الجهاد؛ لما فيه من تعريض النفس والمال.\nس: والعِلم؟\nالشيخ: العِلم من الجهاد، ما هو تطوع، واجب العلم، التعلم واجب.\nس: العلم الكفائي؟\nالشيخ: تَعَلُّم العِلم الذي يعرف به دينه ويعرف ما أوجب الله عليه وما حرم عليه؛ هذا واجب، أما الزيادة فالجهاد أفضل.","link":"https://binbaz.org.sa/fatwas/22999/هل-افضل-العبادات-البدنية-الصلاة-ام-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أفضل العبادات البدنية.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2846,"question":"أفضل العبادات البدنية الصلاة أو الجهاد؟","title":"هل أفضل العبادات البدنية: الصلاة أم الجهاد؟","answer":"الجواب: الجهاد أفضل، في التطوع الجهاد؛ لما فيه من تعريض النفس والمال.\nس: والعِلم؟\nالشيخ: العِلم من الجهاد، ما هو تطوع، واجب العلم، التعلم واجب.\nس: العلم الكفائي؟\nالشيخ: تَعَلُّم العِلم الذي يعرف به دينه ويعرف ما أوجب الله عليه وما حرم عليه؛ هذا واجب، أما الزيادة فالجهاد أفضل.","link":"https://binbaz.org.sa/fatwas/22999/هل-افضل-العبادات-البدنية-الصلاة-ام-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أفضل العبادات البدنية.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2848,"question":"كيف يكون جهاد الأعداء باللسان؟","title":"كيف يكون جهادُ الأعداء باللسان؟","answer":"الجواب: بالذم والهِجاء إذا لم تنفع الدعوة، وتشجيع المقاتلين؛ تجرئتهم على القتال، وذِكْر ما لهم من الخير العظيم والأجر الكبير، يشجّع المجاهدين، ويهجُو المشركين ويُخَذِّلُهم، إلى غير هذا من أنواع الجهاد. والدعوة إذا كان يرجو إسلامهم، من جهادهم باللسان: الدعوة؛ إذا رُجِي إسلامهم.","link":"https://binbaz.org.sa/fatwas/23001/كيف-يكون-جهاد-الاعداء-باللسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جهاد الأعداء باللسان.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2848,"question":"كيف يكون جهاد الأعداء باللسان؟","title":"كيف يكون جهادُ الأعداء باللسان؟","answer":"الجواب: بالذم والهِجاء إذا لم تنفع الدعوة، وتشجيع المقاتلين؛ تجرئتهم على القتال، وذِكْر ما لهم من الخير العظيم والأجر الكبير، يشجّع المجاهدين، ويهجُو المشركين ويُخَذِّلُهم، إلى غير هذا من أنواع الجهاد. والدعوة إذا كان يرجو إسلامهم، من جهادهم باللسان: الدعوة؛ إذا رُجِي إسلامهم.","link":"https://binbaz.org.sa/fatwas/23001/كيف-يكون-جهاد-الاعداء-باللسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جهاد الأعداء باللسان.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2883,"question":"كفار العرب هل يجوز استرقاقهم؟","title":"هل يجوز استرقاق كفار العرب؟","answer":"الجواب: ينبغي أن يُشجعوا على الاستقامة والدخول في الإسلام؛ لئلا يُسترّقوا، وإلا الصحابة استرَّقوا بني حنيفة، لا حرج، النبي ﷺ قال لجارية عند عائشة: أعْتِقيها فإنها من ولد إسماعيل لا بأس. \nوقال: كمن أعتق أربعة أنفس من ولد إسماعيل. فالعرب يُسترّقون بالوجه الشرعي إذا كانوا كفارًا.","link":"https://binbaz.org.sa/fatwas/23038/هل-يجوز-استرقاق-كفار-العرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز استرقاق كفار العرب.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":2883,"question":"كفار العرب هل يجوز استرقاقهم؟","title":"هل يجوز استرقاق كفار العرب؟","answer":"الجواب: ينبغي أن يُشجعوا على الاستقامة والدخول في الإسلام؛ لئلا يُسترّقوا، وإلا الصحابة استرَّقوا بني حنيفة، لا حرج، النبي ﷺ قال لجارية عند عائشة: أعْتِقيها فإنها من ولد إسماعيل لا بأس. \nوقال: كمن أعتق أربعة أنفس من ولد إسماعيل. فالعرب يُسترّقون بالوجه الشرعي إذا كانوا كفارًا.","link":"https://binbaz.org.sa/fatwas/23038/هل-يجوز-استرقاق-كفار-العرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز استرقاق كفار العرب.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":3017,"question":"\"لا يَسِيرُ بالسَّرِيَّة\": هل مِنْ شَرْط الإمارة أنه يخرج مع السَّرِيَّة؟","title":"هل مِنْ شرط الأمير أن يخرج مع السَّرِيَّة؟","answer":"الجواب: على زعمهم أنه جبان، هذا هو، قاتلهم الله، وهو رئيس السرية يوم القادسية وفتح الله على يديه، نسأل الله العافية.\nس: لكن ما هو شرط أن الأمير يخرج معهم؟\nالشيخ: ما هو بلزوم.","link":"https://binbaz.org.sa/fatwas/23175/هل-من-شرط-الامير-ان-يخرج-مع-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من شرط الإمارة أنه يخرج مع السرية.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":3017,"question":"\"لا يَسِيرُ بالسَّرِيَّة\": هل مِنْ شَرْط الإمارة أنه يخرج مع السَّرِيَّة؟","title":"هل مِنْ شرط الأمير أن يخرج مع السَّرِيَّة؟","answer":"الجواب: على زعمهم أنه جبان، هذا هو، قاتلهم الله، وهو رئيس السرية يوم القادسية وفتح الله على يديه، نسأل الله العافية.\nس: لكن ما هو شرط أن الأمير يخرج معهم؟\nالشيخ: ما هو بلزوم.","link":"https://binbaz.org.sa/fatwas/23175/هل-من-شرط-الامير-ان-يخرج-مع-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من شرط الإمارة أنه يخرج مع السرية.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":3019,"question":"أسرى المسلمين إذا خَشَوا أن يُؤتى المسلمين من ناحيتهم، إذ يخافون إفشاء معلومات، هل يقتلون أنفسهم؟","title":"هل يجوز للأسير قتلُ نفسه لمصلحة المسلمين؟","answer":"الجواب: لا، ما يجوز، لا يقتلون أنفسهم، يجتهدون في السلامة، والحمد لله، ولا يقتلون أنفسهم.","link":"https://binbaz.org.sa/fatwas/23178/هل-يجوز-للاسير-قتل-نفسه-لمصلحة-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للأسير قتل نفسه إذا خشي أن يؤتى المسلمين من ناحيته.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":3019,"question":"أسرى المسلمين إذا خَشَوا أن يُؤتى المسلمين من ناحيتهم، إذ يخافون إفشاء معلومات، هل يقتلون أنفسهم؟","title":"هل يجوز للأسير قتلُ نفسه لمصلحة المسلمين؟","answer":"الجواب: لا، ما يجوز، لا يقتلون أنفسهم، يجتهدون في السلامة، والحمد لله، ولا يقتلون أنفسهم.","link":"https://binbaz.org.sa/fatwas/23178/هل-يجوز-للاسير-قتل-نفسه-لمصلحة-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للأسير قتل نفسه إذا خشي أن يؤتى المسلمين من ناحيته.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":3543,"question":"الحديث السابق حديث خيبر - اللَّهُ أَكْبَرُ، خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ-، هل يشرع للمسلمين أن يقولوا: إذا دخلوا أرض عدو، أن يقولوا: الله أكبر خربت بلد كذا فإذا نزلنا بساحة قوم؟","title":"حكم قول: \"الله أكبر خربت كذا\" بأرض العدو","answer":"الجواب: التكبير مشروع للجيش إذا صعدوا مرتفعا كبروا، وإذا نزلوا منخفضا سبحوا، هذا كان النبي ﷺ يفعله والمسلمون، وإذا قاله عند دخوله البلاد هذه نعمة الله أكبر طيب.\nس: السؤال أحسن الله إليك يقولون: الله أكبر خربت بلد كذا فإذا نزلنا بساحة قوم فساء صباح المنذرين؟\nالشيخ: هذا ما فيه مانع الله أكبر نعم.","link":"https://binbaz.org.sa/fatwas/23725/حكم-قول-الله-اكبر-خربت-كذا-بارض-العدو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشرع للمسلمين إذا دخلوا أرض عدو أن يقولوا الله أكبر خربت بلد كذا..mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":3543,"question":"الحديث السابق حديث خيبر - اللَّهُ أَكْبَرُ، خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ-، هل يشرع للمسلمين أن يقولوا: إذا دخلوا أرض عدو، أن يقولوا: الله أكبر خربت بلد كذا فإذا نزلنا بساحة قوم؟","title":"حكم قول: \"الله أكبر خربت كذا\" بأرض العدو","answer":"الجواب: التكبير مشروع للجيش إذا صعدوا مرتفعا كبروا، وإذا نزلوا منخفضا سبحوا، هذا كان النبي ﷺ يفعله والمسلمون، وإذا قاله عند دخوله البلاد هذه نعمة الله أكبر طيب.\nس: السؤال أحسن الله إليك يقولون: الله أكبر خربت بلد كذا فإذا نزلنا بساحة قوم فساء صباح المنذرين؟\nالشيخ: هذا ما فيه مانع الله أكبر نعم.","link":"https://binbaz.org.sa/fatwas/23725/حكم-قول-الله-اكبر-خربت-كذا-بارض-العدو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشرع للمسلمين إذا دخلوا أرض عدو أن يقولوا الله أكبر خربت بلد كذا..mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":4634,"question":"مشاركة النساء في الجهاد؟","title":"كيف تشارك النساء في الجهاد؟","answer":"الجواب: ليس عليهن جهاد، لكن إذا شاركن لمصلحة المسلمين مثل: التمريض وسقي الجرحى، ومثل: حفظ المتاع، مثلما كان يغزو بعضُ النساء مع النبي ﷺ لمصلحةٍ، لا لمباشرة القتال.","link":"https://binbaz.org.sa/fatwas/24924/كيف-تشارك-النساء-في-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مشاركة النساء في الجهاد.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":4634,"question":"مشاركة النساء في الجهاد؟","title":"كيف تشارك النساء في الجهاد؟","answer":"الجواب: ليس عليهن جهاد، لكن إذا شاركن لمصلحة المسلمين مثل: التمريض وسقي الجرحى، ومثل: حفظ المتاع، مثلما كان يغزو بعضُ النساء مع النبي ﷺ لمصلحةٍ، لا لمباشرة القتال.","link":"https://binbaz.org.sa/fatwas/24924/كيف-تشارك-النساء-في-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مشاركة النساء في الجهاد.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":4688,"question":"حكم أخذ السلب في مكة والمدينة؟ أو في المدينة وحدها؟","title":"حكم أخذ السلب في مكة والمدينة","answer":"الجواب: في المدينة فقط. في مكة الجزاء، أما في المدينة فالسلب فقط.\nس: إذا كان لا يستطيع أخذ السلب إلا بمقاومةٍ؟\nج: ما هو بلزوم، إن تيسر وإلا فما هو بلازم، لكن سعدًا  أحبَّ أن يأخذه، قال: غنيمة، وإلا لو تركه فحقٌّ له إذا سمحه.\nس: الأمر للاستحباب فله سلبه؟\nج: للإباحة والعقوبة، إباحة للآخذ، وعقوبة للجاني.\nس: تُقاس عليه السيارة؟\nج: محل نظرٍ، الأقرب عدم القياس؛ لأنها أشد وأخطر.","link":"https://binbaz.org.sa/fatwas/24980/حكم-اخذ-السلب-في-مكة-والمدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أخذ السلب في مكة والمدينة.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":4688,"question":"حكم أخذ السلب في مكة والمدينة؟ أو في المدينة وحدها؟","title":"حكم أخذ السلب في مكة والمدينة","answer":"الجواب: في المدينة فقط. في مكة الجزاء، أما في المدينة فالسلب فقط.\nس: إذا كان لا يستطيع أخذ السلب إلا بمقاومةٍ؟\nج: ما هو بلزوم، إن تيسر وإلا فما هو بلازم، لكن سعدًا  أحبَّ أن يأخذه، قال: غنيمة، وإلا لو تركه فحقٌّ له إذا سمحه.\nس: الأمر للاستحباب فله سلبه؟\nج: للإباحة والعقوبة، إباحة للآخذ، وعقوبة للجاني.\nس: تُقاس عليه السيارة؟\nج: محل نظرٍ، الأقرب عدم القياس؛ لأنها أشد وأخطر.","link":"https://binbaz.org.sa/fatwas/24980/حكم-اخذ-السلب-في-مكة-والمدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أخذ السلب في مكة والمدينة.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":4720,"question":"قوله: كحُرمة شهركم هذا فيه تمسك لمَن قال: أن الأشهر الحرم لم تُنسخ؟","title":"ما صحة القول بنسخ القتال في الأشهر الحرم؟","answer":"فيه حجة لمن قال من العلماء أنَّ الأشهر الحرم باقية، وهي المحرم وذو القعدة وذو الحجة، ثلاثة، والرابع رجب الفرد، هذه الأربعة الجمهور على أنه نُسخ فيها القتال، وأنه لا بأس، وذهب بعضُ أهل العلم إلى أنه باقٍ؛ قال تعالى: يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ في سورة البقرة [217].","link":"https://binbaz.org.sa/fatwas/25016/ما-صحة-القول-بنسخ-القتال-في-الاشهر-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل نُسخت الأشهر الحرم.mp3","categories":["الجهاد والسير"]},{"id":4872,"question":"إجلاء عمر من الجزيرة هذا يدل على أن للمسلمين إجلاء الكفار الآخرين من بلادهم؟","title":"هل يجوز للمسلمين إجلاء الكفار من بلادهم؟","answer":"لا بأس من الجزيرة العربية خاص بالجزيرة العربية. وفي البلدان الأخرى لا بأس أن يقروا فيها بالجزية إذا استطاع المسلمون إقرارهم بالجزية.\nس: وجودهم في عهد الرسول ﷺ عندما أقرهم؟\nج: قبل أن ينسخ.\nس: وفي عهد أبي بكر؟\nج: لعله شغل بأهل الردة.","link":"https://binbaz.org.sa/fatwas/25358/هل-يجوز-للمسلمين-اجلاء-الكفار-من-بلادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للمسلمين إجلاء الكفار من بلادهم.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":4872,"question":"إجلاء عمر من الجزيرة هذا يدل على أن للمسلمين إجلاء الكفار الآخرين من بلادهم؟","title":"هل يجوز للمسلمين إجلاء الكفار من بلادهم؟","answer":"لا بأس من الجزيرة العربية خاص بالجزيرة العربية. وفي البلدان الأخرى لا بأس أن يقروا فيها بالجزية إذا استطاع المسلمون إقرارهم بالجزية.\nس: وجودهم في عهد الرسول ﷺ عندما أقرهم؟\nج: قبل أن ينسخ.\nس: وفي عهد أبي بكر؟\nج: لعله شغل بأهل الردة.","link":"https://binbaz.org.sa/fatwas/25358/هل-يجوز-للمسلمين-اجلاء-الكفار-من-بلادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للمسلمين إجلاء الكفار من بلادهم.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":5099,"question":"فضيلة الشيخ هنا سائل يسأل ويقول: هل الجهاد في هذا الزمان فرض كفاية أم فرض عين؟ وما الفرق بينهما، وما هي شروطهما؟","title":"هل الجهاد في زماننا فرض عين أو كفاية؟","answer":"الجواب: الجهاد أصله فرض كفاية، هذا هو الأصل، فإذا قام به من يكفي سقط عن الباقين، ولهذا كان النبي ﷺ يجاهد بنفسه ويرسل البعوث والسرايا وبقية المسلمين يقيمون في البلاد للمسائل الأخرى والحاجات الأخرى.  وقد يتعين إذا استنفر الإمام من يصلح للجهاد فيتعين عليه؛ لقوله ﷺ: وإذا استنفرتم فانفروا. ويتعين أيضا إذا هجم العدو على البلاد الإسلامية، يتعين على المسلمين أن يصدوه وأن يقاتلوه حتى ينقذوا البلاد منه كما قد وقع في أفغانستان الآن. وهكذا في حال ثالثة وهي ما إذا كان الرجل في الصفين في صف المسلمين ضد عدوهم وقت قيام الجهاد واصطفاف المجاهدين لقتال عدوهم؛ فإنه ليس له أن يخذلهم وليس له أن ينحرف، بل عليه أن يجاهد مع إخوانه ويلتزم. وما سوى ذلك فهو سنة ومن أفضل الأعمال، بل هو أفضل عمل يتطوع به الإنسان، الجهاد؛ لأنه جاء فيه من النصوص ما لم يأت في غيره، في فضل الجهاد.","link":"https://binbaz.org.sa/fatwas/30007/هل-الجهاد-في-زماننا-فرض-عين-او-كفاية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 24.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":5099,"question":"فضيلة الشيخ هنا سائل يسأل ويقول: هل الجهاد في هذا الزمان فرض كفاية أم فرض عين؟ وما الفرق بينهما، وما هي شروطهما؟","title":"هل الجهاد في زماننا فرض عين أو كفاية؟","answer":"الجواب: الجهاد أصله فرض كفاية، هذا هو الأصل، فإذا قام به من يكفي سقط عن الباقين، ولهذا كان النبي ﷺ يجاهد بنفسه ويرسل البعوث والسرايا وبقية المسلمين يقيمون في البلاد للمسائل الأخرى والحاجات الأخرى.  وقد يتعين إذا استنفر الإمام من يصلح للجهاد فيتعين عليه؛ لقوله ﷺ: وإذا استنفرتم فانفروا. ويتعين أيضا إذا هجم العدو على البلاد الإسلامية، يتعين على المسلمين أن يصدوه وأن يقاتلوه حتى ينقذوا البلاد منه كما قد وقع في أفغانستان الآن. وهكذا في حال ثالثة وهي ما إذا كان الرجل في الصفين في صف المسلمين ضد عدوهم وقت قيام الجهاد واصطفاف المجاهدين لقتال عدوهم؛ فإنه ليس له أن يخذلهم وليس له أن ينحرف، بل عليه أن يجاهد مع إخوانه ويلتزم. وما سوى ذلك فهو سنة ومن أفضل الأعمال، بل هو أفضل عمل يتطوع به الإنسان، الجهاد؛ لأنه جاء فيه من النصوص ما لم يأت في غيره، في فضل الجهاد.","link":"https://binbaz.org.sa/fatwas/30007/هل-الجهاد-في-زماننا-فرض-عين-او-كفاية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 24.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":5141,"question":"يقول هذا السَّائل سماحة الشيخ: ما حكم مَن تخاذل في الدِّفاع عن راية الإسلام والدفاع عن الوطن؟ هل يُعتبر كافرًا أو مُرتدًّا؟","title":"حكم التخاذل في الدِّفاع عن الإسلام والوطن","answer":"الجواب: لا، يكون عاصيًا، إذا تأخَّر يكون عاصيًا؛ لأن الواجب عليه أن يُشارك، فالله يقول: وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ [الأنفال:60]، ويقول: خُذُوا حِذْرَكُمْ [النساء:71]، ويقول النبيُّ ﷺ: وإذا استُنْفِرْتُم فانفروا، ويقول الربُّ جلَّ وعلا: إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا [التوبة:39]. فالواجب إذا دعت الحاجةُ إلى هذا أن ينفر، وأن يستجيب لداعي النَّفير من جهة الدولة التي فيها ضد المُغْتَصِب، وضد الظالم، وضد العدو، فإذا تأخَّر وجبن صار عاصيًا بذلك، ولا يكون كافرًا.","link":"https://binbaz.org.sa/fatwas/30056/حكم-التخاذل-في-الدفاع-عن-الاسلام-والوطن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 77.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":5141,"question":"يقول هذا السَّائل سماحة الشيخ: ما حكم مَن تخاذل في الدِّفاع عن راية الإسلام والدفاع عن الوطن؟ هل يُعتبر كافرًا أو مُرتدًّا؟","title":"حكم التخاذل في الدِّفاع عن الإسلام والوطن","answer":"الجواب: لا، يكون عاصيًا، إذا تأخَّر يكون عاصيًا؛ لأن الواجب عليه أن يُشارك، فالله يقول: وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ [الأنفال:60]، ويقول: خُذُوا حِذْرَكُمْ [النساء:71]، ويقول النبيُّ ﷺ: وإذا استُنْفِرْتُم فانفروا، ويقول الربُّ جلَّ وعلا: إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا [التوبة:39]. فالواجب إذا دعت الحاجةُ إلى هذا أن ينفر، وأن يستجيب لداعي النَّفير من جهة الدولة التي فيها ضد المُغْتَصِب، وضد الظالم، وضد العدو، فإذا تأخَّر وجبن صار عاصيًا بذلك، ولا يكون كافرًا.","link":"https://binbaz.org.sa/fatwas/30056/حكم-التخاذل-في-الدفاع-عن-الاسلام-والوطن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 77.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":5312,"question":"ما حكم الجهاد في البوسنة والهرسك في ظل الأوضاع الحالية والهجمة الصليبية الشرسة على المسلمين هناك، بالنسبة لأهل البوسنة وما جاورها من المسلمين القاطنين في بلدان أوروبية، وبالنسبة لساكني الدول العربية والإسلامية، علمًا بأن معظم القادة الميدانيين هناك يقولون بأنهم بحاجة إلى السلاح والرجال وبالذات من العرب؟","title":"ما حكم الجهاد في البوسنة والهرسك؟","answer":"الجواب: المسلمون هناك في أشد الحاجة إلى الدعم والمساعدة بالرجال والمال والسلاح في البوسنة والهرسك، هم في أشد الحاجة إلى الدعم والمساعدة، والجهاد واجب ومساعدتهم واجبة على حكام المسلمين وعلى كل أحد، لكن متى قام بها من يكفي سقط عن الآخرين؛ لأنه وجوب كفائي، فرض كفاية، وحالتهم الآن محزنة والأعداء قد تكالبوا عليهم فهم في أشد الحاجة إلى الدعم والمساعدة وإلى أن يُسمح لهم بشراء السلاح حتى يدافعوا عن أنفسهم ضد هذا العدو الخبيث الصرب، نسأل الله أن يمنحهم التوفيق وأن ينصرهم على عدوهم، وأن يكبت أعداء الإسلام وأن يجعل الدائرة عليهم.[1]","link":"https://binbaz.org.sa/fatwas/30972/ما-حكم-الجهاد-في-البوسنة-والهرسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 033.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":5312,"question":"ما حكم الجهاد في البوسنة والهرسك في ظل الأوضاع الحالية والهجمة الصليبية الشرسة على المسلمين هناك، بالنسبة لأهل البوسنة وما جاورها من المسلمين القاطنين في بلدان أوروبية، وبالنسبة لساكني الدول العربية والإسلامية، علمًا بأن معظم القادة الميدانيين هناك يقولون بأنهم بحاجة إلى السلاح والرجال وبالذات من العرب؟","title":"ما حكم الجهاد في البوسنة والهرسك؟","answer":"الجواب: المسلمون هناك في أشد الحاجة إلى الدعم والمساعدة بالرجال والمال والسلاح في البوسنة والهرسك، هم في أشد الحاجة إلى الدعم والمساعدة، والجهاد واجب ومساعدتهم واجبة على حكام المسلمين وعلى كل أحد، لكن متى قام بها من يكفي سقط عن الآخرين؛ لأنه وجوب كفائي، فرض كفاية، وحالتهم الآن محزنة والأعداء قد تكالبوا عليهم فهم في أشد الحاجة إلى الدعم والمساعدة وإلى أن يُسمح لهم بشراء السلاح حتى يدافعوا عن أنفسهم ضد هذا العدو الخبيث الصرب، نسأل الله أن يمنحهم التوفيق وأن ينصرهم على عدوهم، وأن يكبت أعداء الإسلام وأن يجعل الدائرة عليهم.[1]","link":"https://binbaz.org.sa/fatwas/30972/ما-حكم-الجهاد-في-البوسنة-والهرسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 033.mp3","categories":["الجهاد والسير","الجهاد والسير"]},{"id":5878,"question":"هل الجهاد في سبيل الله جهاد أصغر كما دل عليه معنى الحديث المذكور الضعيف، مع أنه لا يمكن أن يجاهد في سبيل الله إلا من جاهد نفسه حق الجهاد، وألزمها حتى أراد أن يستشهد في سبيل الله؟","title":"بيان الجهاد الأصغر والجهاد الأكبر","answer":"الجواب: الجهاد في سبيل الله هو الجهاد الأكبر كما تقدم، وهو الجهاد الأكبر؛ ولهذا أنكر العلماء هذا الحديث، وقالوا: إنه يقتضي أن الجهاد في سبيل الله هو الجهاد الأصغر، فهذا خطأ؛ فإن بذل النفوس، والأموال في جهاد الأعداء، ودعوتهم إلى الإسلام، وإخراجهم من ظلمات الجهل، والكفر هذا أمر عظيم فوق ما يتصوره الناس.  فلهذا صار الجهاد في سبيل الله الذي به بذل النفوس، وبذل الأموال، ومغادرة البلدان، والغربة عن الأوطان، والأولاد، والنساء، هذا هو الجهاد الأعظم، ثم يرجع الناس منه إلى الجهاد الأصغر، جهاد النفس على ما يعتريها من المعاصي، والسيئات، وعلى ما تقيم عليه من خطر، ونقصان، فهو يجاهدها لله حتى تستقيم.  ولا شك أن الجهاد الأكبر إنما يحصل في الجهاد الأصغر، جهاد النفس حتى تستقيم على أمر الله، حتى ترضى بالجهاد في سبيل الله، حتى تقدم النفس، والمال.  هذا هو شأن المؤمن، يجاهد نفسه، ويتصبر على جهاد الكفار لما يعلم في ذلك من الخير العظيم، وقد ثبت عن رسول الله ﷺ فيما رواه البخاري، وغيره أنه قال: ما من أحد يموت له خير عند الله يتمنى أن يرجع إلى الحياة الدنيا إلا الشهيد، فإنه يتمنى أن يرجع إلى الدنيا، فيقتل عشر مرات؛ لما يرى من فضل الشهادة في سبيل الله  والنبي ﷺ يقول: إني أود أن أقتل في سبيل الله، ثم أحيا، ثم أقتل، ثم أحيا، ثم أقتل.","link":"https://binbaz.org.sa/fatwas/1231/بيان-الجهاد-الاصغر-والجهاد-الاكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_228.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":5890,"question":"هل الجهاد في سبيل الله جهاد أصغر كما دل عليه معنى الحديث المذكور الضعيف، مع أنه لا يمكن أن يجاهد في سبيل الله إلا من جاهد نفسه حق الجهاد، وألزمها حتى أراد أن يستشهد في سبيل الله؟","title":"بيان الجهاد الأصغر والجهاد الأكبر","answer":"الجواب: الجهاد في سبيل الله هو الجهاد الأكبر كما تقدم، وهو الجهاد الأكبر؛ ولهذا أنكر العلماء هذا الحديث، وقالوا: إنه يقتضي أن الجهاد في سبيل الله هو الجهاد الأصغر، فهذا خطأ؛ فإن بذل النفوس، والأموال في جهاد الأعداء، ودعوتهم إلى الإسلام، وإخراجهم من ظلمات الجهل، والكفر هذا أمر عظيم فوق ما يتصوره الناس.  فلهذا صار الجهاد في سبيل الله الذي به بذل النفوس، وبذل الأموال، ومغادرة البلدان، والغربة عن الأوطان، والأولاد، والنساء، هذا هو الجهاد الأعظم، ثم يرجع الناس منه إلى الجهاد الأصغر، جهاد النفس على ما يعتريها من المعاصي، والسيئات، وعلى ما تقيم عليه من خطر، ونقصان، فهو يجاهدها لله حتى تستقيم.  ولا شك أن الجهاد الأكبر إنما يحصل في الجهاد الأصغر، جهاد النفس حتى تستقيم على أمر الله، حتى ترضى بالجهاد في سبيل الله، حتى تقدم النفس، والمال.  هذا هو شأن المؤمن، يجاهد نفسه، ويتصبر على جهاد الكفار لما يعلم في ذلك من الخير العظيم، وقد ثبت عن رسول الله ﷺ فيما رواه البخاري، وغيره أنه قال: ما من أحد يموت له خير عند الله يتمنى أن يرجع إلى الحياة الدنيا إلا الشهيد، فإنه يتمنى أن يرجع إلى الدنيا، فيقتل عشر مرات؛ لما يرى من فضل الشهادة في سبيل الله  والنبي ﷺ يقول: إني أود أن أقتل في سبيل الله، ثم أحيا، ثم أقتل، ثم أحيا، ثم أقتل.","link":"https://binbaz.org.sa/fatwas/1231/بيان-الجهاد-الاصغر-والجهاد-الاكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_228.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":5892,"question":"هل الهجرة أفضل، أم الجهاد في بلد يدعي الإسلام، وهي تحاربه؟","title":"بيان الأفضلية بين الهجرة أو البقاء لمواجهة المنكر","answer":"الجواب: هذا يختلف إذا كان هناك في البلد من يستطيع الجهاد، ورد الباطل، وإقامة الحق، والميزان، فهذا له شأن؛ فالأفضل بقاؤه في بلده التي فيها الشر، يجاهد فيها، ويدعو إلى الله، ويعلم الناس الخير، ويستطيع إظهار دينه، هذا أفضل من هجرته إذا كان يستطيع ذلك.  أما إذا كان لا يستطيع، بل يقمع، ويخشى على نفسه؛ فالهجرة له أولى من بقائه بين قوم يقهرونه على الباطل، ويمنعوه من الحق، ويخشى عليه من الفساد، وانحراف القلب عن الهدى، والميل إلى الدعة، والسكون، والراحة حتى يأنس بالشرك، والفساد، ولا حول، ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/1233/بيان-الافضلية-بين-الهجرة-او-البقاء-لمواجهة-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_230.mp3","categories":["الجهاد والسير"]},{"id":5994,"question":"ما معنى قول الرسول ﷺ: نصرت بالرعب مسيرة شهر؟ وهل هو خاص به ﷺ أم له، ولأمته من بعده؟","title":"معنى: «نصرت بالرعب مسيرة شهر»","answer":"الجواب:  قول النبي ﷺ: نصرت بالرعب مسيرة شهر على ظاهره، وأن الله -جل وعلا- يلقي في قلوب أعدائه الرعب، وهم عنه بعيدون مسافة شهر كالشام عن المدينة، والعراق، ونحو ذلك، ينصره الله عليهم بالرعب.  فإذا وصل إليهم إذ الرعب قد تمكن منهم، وكان ذلك من أسباب نصره عليهم، ومن أسباب خذلانهم، وانخلاع قلوبهم عن المقاومة، وهكذا في أمته، هذا ليس خاصًا به ﷺ بل أعطاه الله، وأمته ذلك.  فأمته المستقيمة على دينه، والصابرون على دينه، والمقيمون لشريعته ينصرها الله كما نصره، ويلقي في قلوب عدوها الرعب مسافة شهر، كما نصر نبيه بذلك -عليه الصلاة والسلام- لأن هذا من جملة خصائصه التي له، ولأمته -عليه الصلاة والسلام- فمن استقام على دينه، وجاهد في سبيله ابتغاء مرضاته، وإعلاء لكلمته، فالله ينصره، ويؤيده، ويلقي الرعب في قلوب عدوه مسافة شهر.","link":"https://binbaz.org.sa/fatwas/1412/معنى-نصرت-بالرعب-مسيرة-شهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_358.mp3","categories":["الجهاد والسير","شروح الحديث"]},{"id":5996,"question":"فضيلة الشيخ إن جنود المسلمين الآن لا يمسون إلا على الأفلام الخليعة، وثقافاتهم الدينية ضحلة جدًا، أليس هذا من التقصير في الأخذ بالأسباب؟ والمسلمون الذين يريدون الجهاد لا يعرفون أن يرموا بحجر؛ لأن في كثير من البلاد السلاح ممنوع شراؤه، وحمله، والتدريب عليه؟ فإذا دعا داع الجهاد فكيف تكون الحالة؟","title":"حقيقة الجيوش العربية والإسلامية وكيفية إعدادهم","answer":"الجواب:  هذا من أعظم الأسباب لعدم الإعداد، الإقبال على الشهوات، وعلى الأفلام الخليعة، وعلى الإذاعات، والتلفزة، والمسجلات الخبيثة، وشغل الوقت بها عن طاعة الله، ورسوله؛ فهذا من أعظم الخسارة، ومن أعظم أسباب تسليط الأعداء، ومن أعظم أسباب حلول العقوبات، نعوذ بالله من ذلك. وكذلك كون الإنسان لا يتدرب، ولا يجد من يدربه على السلاح، وعلى الجهاد في سبيل الله، ويدرب بدنه على حمل السلاح، فهذا أيضًا من المصائب، والنكبات، فيجب على كل دولة أن تدرب رجالها، وشبابها حتى يكونوا عدة صالحة للجهاد، والقتال، وأن لا يهملوا، فإذا استعدوا وقت نزول الكارثة لا ينفع إنما يستعدون قبل ذلك بالإعداد، والتدريب، حتى إذا جاءت الحاجة، ونزلت النازلة، إذا هو صالح للعمل، وصالح للجهاد.  نسأل الله أن يوفق ولاة المسلمين لهذا الأمر، وأن يعدل الشباب، ومن فيه القوة أن يطالب بذلك، ويعتني بذلك، حتى يكون صالحًا للجهاد، وحتى يكون مدربًا إذا جاءت الحقائق، وجاء أعداء الله، أو أريد قتال أعداء الله.","link":"https://binbaz.org.sa/fatwas/1398/حقيقة-الجيوش-العربية-والاسلامية-وكيفية-اعدادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_353.mp3","categories":["الجهاد والسير","قضايا معاصرة"]},{"id":6001,"question":"قرأت مقالًا لأحد العلماء أن ما يمر بالمسلمين من تسلط للأعداء، واحتلال لمقدساتهم أنه فرض عين على كل مسلم في الدفاع عما هم فيه من اضطهاد، فما رأيكم في هذا، أجيبونا، جزاكم الله خيرًا؟","title":"واجب المسلمين في الدفاع عن دينهم وأرضهم","answer":"الجواب: سبق الكلام في هذا، وأن الواجب على المسلمين: التكاتف، والتعاون ضد أعدائهم؛ لإنقاذ بلادهم من أيدي اليهود، وغير ذلك، يجب على المسلمين التكاتف، والتعاون لجهاد أعداء الله؛ لاستنقاذ البلاد التي هي لليهود، ولقتال كل من خرج عن دين الله، ولم يحكم شريعة الله.","link":"https://binbaz.org.sa/fatwas/1393/واجب-المسلمين-في-الدفاع-عن-دينهم-وارضهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_349.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":6131,"question":"ما معنى العبارة: (لحق بالرفيق الأعلى) عندما مات رسول الله ﷺ؟","title":"بيان معنى قوله: \"لحق بالرفيق الأعلى\"","answer":"الجواب: الرفيق الأعلى هم الرسل، والأنبياء، والصالحون الذين قال فيهم -جل وعلا-: وَمَنْ يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا [النساء:69] وقال عند الموت: اللهم في الرفيق الأعلى لأن هؤلاء الرفيق الأعلى قد دخلوا الجنة، وصاروا إليها من الرسل، وأتباعهم، وهو يطلب ربه أن يكون معهم، مع أولئك الأخيار الذين أطاعوا الله، ورسوله، وصاروا إلى الجنة، والكرامة، هم الرفيق الأعلى المقصودين في قوله سبحانه: وَمَنْ يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا [النساء:69] الله يجعلنا وإياكم منهم.","link":"https://binbaz.org.sa/fatwas/1572/بيان-معنى-قوله-لحق-بالرفيق-الاعلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_477.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6323,"question":"وآخر يقول: أريد الجهاد في سبيل الله، وفي أفغانستان، ولكني لي والدة لا تسمح لي بذلك؛ لأنها تحبني حبًا كثيرًا، فما موقفي منها؟","title":"حكم طاعة الوالدين في عدم الذهاب إلى الجهاد","answer":"الجواب: عليك أن تطيع والدتك، ولا تجاهد إذا قالت أمك: لا فلا، فالجهاد فيها، النبي ﷺ جاءه رجل يستأذنه، فقال: أحي والداك؟ قال: نعم، قال: ارجع فاستأذنهما فإن أذنا وإلا فبرهما، وفي رواية أخرى: ففيهما فجاهد وجاءه رجل .. أمه فقال: الزمها وأمره بعدم مخالفتها، وعدم الخروج عن طاعتها بالذهاب إلى الجهاد.  السؤال: وإن كان له إخوة؟ الجواب: وإن كان له إخوة كلهم عليهم السمع، والطاعة في هذا الأمر؛ لأن الجهاد فرض كفاية. السؤال: إذا كان الأبوان كافرين؟ الجواب: هذا محل نظر؛ إن كانا كافرين فمحل نظر، وإن كان الله قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفاً [لقمان:15] الله أمر بمصاحبتهما معروفًا، وهما كافران، إن كانا على الشرك أمر الله أن يصاحبا بالمعروف، أما كونهما يطاعان في ترك الجهاد فهذا محل نظر.","link":"https://binbaz.org.sa/fatwas/1899/حكم-طاعة-الوالدين-في-عدم-الذهاب-الى-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_682.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":6459,"question":"ورد عن الرسول ﷺ أنه قال : من جاءه من أخيه معروف من غير مسألة، ولا بإشراف نفس؛ فليقبله، ولا يرده، فإنما هو رزق ساقه الله إليه نرجو من سماحتكم مشكورين شرح هذا الحديث؟","title":"شرح حديث: «وما جاءك من هذا المال وأنت غير مشرف»","answer":"الجواب: هذا الحديث رواه مسلم في الصحيح عن ابن عمر -رضي الله عنهما- أن النبي ﷺ أعطى عمر شيئًا من المال كان عمر يريد مالًا، فأعطاه النبي بعض الشيء، فقال عمر: يا رسول الله أعطه من هو أحوج إليه مني، فقال له النبي ﷺ: خذه، وتموله، أو تصدق به، وما جاءك من هذا المال وأنت غير مشرف، ولا سائل؛ فخذه، وما لا فلا تتبعه نفسك. فالنبي ﷺ أمر عمر أن يقبل ما جاءه من بيت المال، ومن جنس هذا المال من غير سؤال، ولا إشراف نفس، فإن شاء تموله، وجعله في حاجاته، وإن شاء تصدق به، فأنت إذا جاءك مال ليس من طريق الربا، ولا من طريق القمار، بل هدية من أخيك فاقبله، أو من بيت المال فاقبله، فإن شئت تموله في حاجاتك، في طعامك، وشرابك، وملابسك في أهل بيتك، وإن شئت فتصدق به على من شئت إذا كنت لا تريده، أو تتبرع عنه، تصدق به على من يحتاج إليه من الفقراء، ولا ترده إلا بأسباب، إلا إذا كان له أسباب الرد.  إذا أعطاك المال من أجل أن تشهد له بالزور لا تقبل هذا المال، إذا أعطي القاضي المال ليحكم عليه بالجور، ليس للقاضي أن يقبل هذا المال، ما يجوز له؛ لأنه يكون رشوة إذا أعطاك المال من أجل معصية تفعلها معه، أو له ما يجوز، أما إذا أعطاك المال أحبك في الله، أو لأنك فقير، أو لأجل الرحم فلا ترده إلا إذا كنت تعلم أنه خبيث، أنه سرقه، أنه ظلمه من زيد، أو عمر، فرده حينئذ؛ لأنه اكتسبه بما حرم الله، وتعدى على عباد الله، أو تأخذه منه، وتعطيه صاحبه إذا عرفت أنه سرقه من فلان، أو ظلمه فلان، أو غصبه من فلان؛ فخذه، ورده إلى صاحبه؛ فتكون صاحب خير، وتكون محسنا بذلك. فالحاصل: أن المال إذا جاءك من طريق لا بأس به، فخذه، ولا ترده، إن شئت تتصرف به لنفسك، وإن شئت فتصدق به، أو اصرفه في مشروع الخير، أما إذا جاء من طريق غير شرعية، من طريق الرشوة، من طريق السرقة، والظلم للناس؛ فلا تقبله، ولا تعن على معاصي الله.","link":"https://binbaz.org.sa/fatwas/2209/شرح-حديث-وما-جاءك-من-هذا-المال-وانت-غير-مشرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_830.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6488,"question":"أحد الأخوة يسأل فيقول: إن له والدة، وهناك من يعولها، ويقوم بشؤونها، ولكنها تخاف عليه دائمًا، وهو يريد الجهاد في سبيل الله، وهي لا تقبل ذلك، فما حكم ذلك؟","title":"حكم استئذان الوالدين في الجهاد في سبيل الله","answer":"الجواب: جهاده فيها أفضل، إذا كان له والدة تريد بقاءه عندها، الجهاد فيها أفضل، النبي ﷺ أمر بعض الناس لما أراد الجهاد أمره أن يلزم أمه، أمره أن يجاهد في برها، وصلتها، والإحسان إليها، وجاءه آخر يريد الجهاد فقال له: أحي والداك؟ قال: نعم. قال: ففيهما فجاهد، وفي رواية: ارجع فاستأذنهما؛ فإن أذن لك، وإلا فبرهما.  فإذا كان له والدة؛ فليلزمها، ولا يجاهد حتى تسمح له، وإذا كان والدان فلا بد من إذنهما في ذلك، وإلا فبره لهما، والإحسان إليهما أعظم من خروجه في الجهاد، في الحديث الصحيح لما سئل أي العمل أفضل؟ قال: الصلاة على وقتها قيل: ثم أي؟ قال: بر الوالدين قيل: ثم أي؟ قال: الجهاد في سبيل الله فجعل الجهاد بعد بر الوالدين، فبرهما واجب، وفريضة، والجهاد قد يكون فريضة، وقد يكون مستحبًا.","link":"https://binbaz.org.sa/fatwas/2230/حكم-استىذان-الوالدين-في-الجهاد-في-سبيل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_850.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":6503,"question":"إذا هم الإنسان بفعل ذنب ما، ومنعه مانع خارجي، هل عليه نفس الوزر إذا فعل هذا الذنب بنص حديث: هما في الوزر سواء وكيف يوفق بين هذا الحديث وحديث: من هم بسيئة، ولم يفعلها؛ كتبت له حسنة؟","title":"الجمع بين: «مًنْ همَّ بسيئة» و «هما في الوزر سواء»","answer":"الجواب: الرسول -عليه الصلاة والسلام- صرح بأن الله  كتب الحسنات والسيئات، وبين ذلك  كما جاء في الصحيحين من حديث ابن عباس، وأن من هم بالسيئة فلم يعملها، لم تكتب عليه، وإن تركها من أجل الله؛ كتبها الله حسنة؛ لأنه تركها من جراء الله، وإن هم بالحسنة كتبها الله حسنة، فإن عملها؛ كتبها الله عشر حسنات، إلى سبعمائة ضعف، إلى أضعاف كثيرة.  وأما ما جاء في حديث أبي كبشة الأنماري: الدنيا لأربعة ذكر منهم: رجل أعطاه الله مالا وعلما فهو يتقي في ماله ربه ويصل فيه رحمه فهو في أعلى المنازل، ورجل أعطاه الله علما ولم يعطه مالا فقال: لو كان لي مثل فلان لعملت فيه مثل عمله، قال فهما في الأجر سواء، والثالث أعطي مالا ولم يعط علما فهو لا يتقي فيه ربه ولا يصل فيه رحمه ولا يعمل لله فيه حقا فهو بشر المنازل -نعوذ بالله، والرابع رجل لم يعط علما ولا مالا فهو يقول : لو كان لي مالا مثل فلان لعملت فيه مثل عمله قال -عليه الصلاة والسلام-: فهما في الوزر سواء بسبب النية الخبيثة، نسأل الله العافية. لا شك أن هذا قد يشكل مع الحديث الصحيح الذي فيه أن النية الطيبة تنفع، ويؤجر صاحبها، والسيئة إذا لم يعمل لا تكتب عليه، وإن تركها من أجل الله كتبت حسنة، وفي حديث أبي كبشة الأنماري أن هذا الرجل الذي قال : لو كان لي مثل فلان -يعني من المال- لعملت مثل عمله السيئ قال: فهما في الوزر سواء.  والجواب عن هذا -والله أعلم-: أن هذا في حق من صمم على هذا، وعزم عليه، ولم يمنعه إلا العجز، وإلا فهو مصمم على أن يعمل بالمعاصي، والسيئات التي يعملها ذاك الرجل الذي أعطاه الله المال بلا علم، فهو مثله في الوزر لتصميمه، وعزمه الصادق، وما علم الله من قلبه من الخبث، والفساد فهو مثل الذي قال فيه النبي ﷺ: إذا التقى المسلمان بسيفهما؛ فالقاتل والمقتول في النار قيل يا رسول الله: هذا القاتل فما بال المقتول؟ قال: لأنه كان حريصًا على قتل صاحبه فجعله معه في النار -نسأل الله العافية- لأنه حريص، ما منعه إلا العجز، وإلا فقد جاء بالسيف، وأعد العدة، وحاول القتل، لكن غلبه صاحبه، فقتله، فهما في النار سواء، هذا بأنه قتل، وهذا بأنه حاول القتل.  فهذا الرجل الذي في حديث أبي كبشة يقول: لو كان لي من المال مثل فلان لعملت فيه مثل عمله يعني مصمم، ومريد هذا، وعنده عزم عليه، وجد لو وجد ذلك، ولكن منعه الفقر ومنعه العجز، فهذا -والعياذ بالله- حري بأن يكون مثله في الفساد، والشر، والإثم، نسأل الله العافية. بخلاف الذي همَّ، ثم ترك؛ فهذا ما عزم، هم، ثم ترك، فهذا ليس عليه شيء، أو ترك من أجل الله، فهذا له حسنة، أما هذا هم، وعزم، وصمم على أنه يعمل مثل فلان، ولكن غلبه صاحبه بالقتل، أو عزم، وصمم، ولكن لم يقدر له المال، ولم يسعف المال، وهو مصمم، فهذا يفيد الحذر من التصميم على السيئات، والعزم عليها، وأن في ذلك خطر عظيم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2245/الجمع-بين-من-هم-بسيىة-و-هما-في-الوزر-سواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_866.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6509,"question":"كيف الجمع بين حديث قتل السكران بعد الرابعة، أي شربه بعد الرابعة، وحديث لا يحل دم امرئ مسلم إلا بإحدى ثلاث؟","title":"الجمع بين: قتل السكران بعد الرابعة، و «لا يحل دم امرئٍ»","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد:  فقد تقدم قبل الصلاة في الندوة، والتعليق عليها ما يدل على شدة تحريم المسكرات، والمخدرات، وعظيم الأضرار، والأخطار المترتبة عليها في الدنيا، والآخرة، وقد ورد عنه ﷺ أنه أمر بقتل شارب الخمر في الرابعة، ولو يحد في الأولى، ويحد في الثانية بالجلد، ويحد في الثالثة بالجلد، فإذا عاد في الرابعة يقتل؛ لأنه بذلك صار معتادًا للفساد، ويعسر تركه، لذلك فكان في قتله إراحة للناس من شره، وحماية له أيضًا من البقاء على التكرار فيما يضره، ولا ينفعه. ولكن جمهور أهل العلم، وأكثر أهل العلم قالوا: إن هذا منسوخ، وإن قتله في الرابعة منسوخ بقوله ﷺ: لا يحل دم امرئ مسلم يشهد ألا إله إلا الله، وأني رسول الله إلا بإحدى ثلاث: الثيب الزاني، والنفس بالنفس، والتارك لدينه المفارق للجماعة. قالوا: وهذا يدل على أن من عدا هؤلاء الثلاثة لا يقتل، بل يعامل بما يجب من حد، وتعزير، ومن قال بقتله قال: إنه مستثنى، وأنه قام عليه الدليل، فيستثنى من هذه الثلاث، ويقتل من أجل فساده في الأرض، وأن تكراره لشرب الخمر، واعتياده لذلك يجعله من المفسدين، ومن المروجين للباطل؛ فيقتل؛ ليراح الناس من شره، والمجتمع من أضراره. وهذا -كما قال المحققون من أهل العلم- محل نظر، فإن ولي الأمر ينظر في هذا الأمر، ويجتهد، فإن رأى قتل من تكررت منه هذه المفسدة؛ قتله، وإن رأى أن يعيد عليه الجلد مرة رابعة، وخامسة، وسادسة؛ فلا بأس، فينظر في الأصلح الذي يرجى فيه مصلحة الأمة، ومرضاة الرب .  وهكذا المروجون من باعة الخمر، وغيرهم من المخدرات، والمفترات، ولي الأمر ينظر في ذلك، فيزيد في العقوبة، والتعزير على حسب كثرة الترويج، والفساد من باعة هذه الأشياء، ومروجيها، وقد يفضي التعزير إلى أن يقتل هذا المروج حتى يراح الناس من نشره الفساد، ولا يصار إلى القتل إلا عند الضرورة، وعند الحاجة القصوى إذا لم يرتدع بالحدود الشرعية، والتعزيرات الشرعية، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2262/الجمع-بين-قتل-السكران-بعد-الرابعة-و-لا-يحل-دم-امرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_885.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6525,"question":"إذا هم الإنسان بفعل ذنب ما، ومنعه مانع خارجي، هل عليه نفس الوزر إذا فعل هذا الذنب بنص حديث: هما في الوزر سواء وكيف يوفق بين هذا الحديث وحديث: من هم بسيئة، ولم يفعلها؛ كتبت له حسنة؟","title":"الجمع بين: «مًنْ همَّ بسيئة» و «هما في الوزر سواء»","answer":"الجواب: الرسول -عليه الصلاة والسلام- صرح بأن الله  كتب الحسنات والسيئات، وبين ذلك  كما جاء في الصحيحين من حديث ابن عباس، وأن من هم بالسيئة فلم يعملها، لم تكتب عليه، وإن تركها من أجل الله؛ كتبها الله حسنة؛ لأنه تركها من جراء الله، وإن هم بالحسنة كتبها الله حسنة، فإن عملها؛ كتبها الله عشر حسنات، إلى سبعمائة ضعف، إلى أضعاف كثيرة.  وأما ما جاء في حديث أبي كبشة الأنماري: الدنيا لأربعة ذكر منهم: رجل أعطاه الله مالا وعلما فهو يتقي في ماله ربه ويصل فيه رحمه فهو في أعلى المنازل، ورجل أعطاه الله علما ولم يعطه مالا فقال: لو كان لي مثل فلان لعملت فيه مثل عمله، قال فهما في الأجر سواء، والثالث أعطي مالا ولم يعط علما فهو لا يتقي فيه ربه ولا يصل فيه رحمه ولا يعمل لله فيه حقا فهو بشر المنازل -نعوذ بالله، والرابع رجل لم يعط علما ولا مالا فهو يقول : لو كان لي مالا مثل فلان لعملت فيه مثل عمله قال -عليه الصلاة والسلام-: فهما في الوزر سواء بسبب النية الخبيثة، نسأل الله العافية. لا شك أن هذا قد يشكل مع الحديث الصحيح الذي فيه أن النية الطيبة تنفع، ويؤجر صاحبها، والسيئة إذا لم يعمل لا تكتب عليه، وإن تركها من أجل الله كتبت حسنة، وفي حديث أبي كبشة الأنماري أن هذا الرجل الذي قال : لو كان لي مثل فلان -يعني من المال- لعملت مثل عمله السيئ قال: فهما في الوزر سواء.  والجواب عن هذا -والله أعلم-: أن هذا في حق من صمم على هذا، وعزم عليه، ولم يمنعه إلا العجز، وإلا فهو مصمم على أن يعمل بالمعاصي، والسيئات التي يعملها ذاك الرجل الذي أعطاه الله المال بلا علم، فهو مثله في الوزر لتصميمه، وعزمه الصادق، وما علم الله من قلبه من الخبث، والفساد فهو مثل الذي قال فيه النبي ﷺ: إذا التقى المسلمان بسيفهما؛ فالقاتل والمقتول في النار قيل يا رسول الله: هذا القاتل فما بال المقتول؟ قال: لأنه كان حريصًا على قتل صاحبه فجعله معه في النار -نسأل الله العافية- لأنه حريص، ما منعه إلا العجز، وإلا فقد جاء بالسيف، وأعد العدة، وحاول القتل، لكن غلبه صاحبه، فقتله، فهما في النار سواء، هذا بأنه قتل، وهذا بأنه حاول القتل.  فهذا الرجل الذي في حديث أبي كبشة يقول: لو كان لي من المال مثل فلان لعملت فيه مثل عمله يعني مصمم، ومريد هذا، وعنده عزم عليه، وجد لو وجد ذلك، ولكن منعه الفقر ومنعه العجز، فهذا -والعياذ بالله- حري بأن يكون مثله في الفساد، والشر، والإثم، نسأل الله العافية. بخلاف الذي همَّ، ثم ترك؛ فهذا ما عزم، هم، ثم ترك، فهذا ليس عليه شيء، أو ترك من أجل الله، فهذا له حسنة، أما هذا هم، وعزم، وصمم على أنه يعمل مثل فلان، ولكن غلبه صاحبه بالقتل، أو عزم، وصمم، ولكن لم يقدر له المال، ولم يسعف المال، وهو مصمم، فهذا يفيد الحذر من التصميم على السيئات، والعزم عليها، وأن في ذلك خطر عظيم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2245/الجمع-بين-من-هم-بسيىة-و-هما-في-الوزر-سواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_866.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6684,"question":"كيف نوفق بين الأحاديث المتعارضة فكريًا في الشرب واقفًا، وفي التبول واقفًا، وجزاكم الله خيرًا؟","title":"كيفية التوفيق بين الأحاديث المتعارضة ظاهرياً في الشرب والتبول واقفاً","answer":"الجواب: الحقيقة ليس فيها تعارض، فالنبي ﷺ نهى عن الشرب قائمًا، ثم فعل ذلك ﷺ، فدل ذلك على أن الأمر ليس للوجوب، وليس النهي للتحريم، فمن شرب قائمًا فلا حرج، ومن جلس فهو أفضل، هذا الجمع بينهما، النبي شرب قائمًا، وقاعدًا -عليه الصلاة والسلام- فالقعود أفضل، وأروى، وأهنأ، وإذا شرب قائمًا للحاجة، والعجلة، أو لأسباب أخرى؛ فلا بأس، فقد ثبت هذا وهذا عن النبي ﷺ، فيدل أن نهيه عن الكراهة، وأن أمره بالقعود للندب ولا.. في ذلك، ولا تعارض.  وهكذا البول قائمًا، والبول قاعدًا، البول قاعدًا أفضل، وأستر، والبول قائمًا جائز إذا كان ما فيه ظهور العورة، إذا كان ما يراه أحد، إذا كان في مكان لا يراه أحد، أو وقف إلى جدار مثلًا، وبال قائمًا لحاجة، أو لسرعة، أو يكون المكان غير لائق، أو ليبين الجواز للناس؛ فلا حرج، فقد ثبت عنه ﷺ أنه كان يبول قاعدًا في الأغلب، وقد ثبت في حديث حذيفة أنه بال قائمًا؛ أتى سباطة قوم فبال قائمًا، وجاء في أحاديث أخرى. فالصواب: أنه يجوز هذا وهذا لكن بشرط ستر العورة، وألا ترى عورته، يكون في مكان مستور، لا ترى فيه العورة، فلا بأس، ولكن الجلوس أفضل. السؤال: في بعض المحلات أماكن مخصوصة للبول قائما مثل المطارات؟ الجواب: لا حرج لا حرج، إذا دعت الحاجة لا حرج، لكن بشرط ستر العورة. السؤال: ما في حاجة يا شيخ هي دورة مياه؟ الجواب: المقصود إذا كان بوله قائما لا ترى عورته، ولا يطبع ثيابه بالنجاسة؛ فلا حرج.","link":"https://binbaz.org.sa/fatwas/2545/كيفية-التوفيق-بين-الاحاديث-المتعارضة-ظاهريا-في-الشرب-والتبول-واقفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1040.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6704,"question":"لما خير النبي -عليه الصلاة والسلام- بين الدنيا، والآخرة اختار الآخرة، وقال: اللهم الرفيق الأعلى فما المقصود بالرفيق الأعلى؟","title":"معنى قوله عليه الصلاة والسلام: «اللهم الرفيق الأعلى»","answer":"الجواب:  يعني مع النبيين، والصديقين، والشهداء، والصالحين، وحسن أولئك رفيقًا.","link":"https://binbaz.org.sa/fatwas/2582/معنى-قوله-عليه-الصلاة-والسلام-اللهم-الرفيق-الاعلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1078.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6850,"question":"ورد حديث عن الرسول ﷺ: إذا التقى المسلمان بسيفهما فالقاتل، والمقتول في النار إذا كان هذا حديث صحيح، فما حكم قتل جيوش المسلمين الذين يقتل بعضهم بعضًا مثل العراق، والإيرانيين، أفيدونا جزاكم الله خيرًا؟","title":"معنى حديث: «إذا التقى المسلمان بسيفيهما»","answer":"الجواب: الحديث صحيح في الصحيحين، عن النبي -عليه الصلاة والسلام- أنه قال: إذا التقى المسلمان بسيفهما فالقاتل، والمقتول في النار قيل يا رسول الله هذا القاتل فما شأن المقتول؟ قال: لأنه كان حريصًا على قتل صاحبه.  فالمسلمان إذا التقوا ظلمًا، وعدوانًا هذا وعيدهم، أما إذا التقوا بشبهة، ولأمر مشروع، كما يقوم أهل العدل في قتال أهل البغي، فهؤلاء الذين قاموا بإزالة البغي محسنون، ومقتولهم شهيد، ويرجى له الخير؛ لأنهم قاموا بإزالة البغي كما قال الله -جل وعلا-: وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا فَأَصْلِحُوا بَيْنَهُمَا فَإِنْ بَغَتْ إِحْدَاهُمَا عَلَى الْأُخْرَى فَقَاتِلُوا الَّتِي تَبْغِي حَتَّى تَفِيءَ إِلَى أَمْرِ اللَّهِ [الحجرات:9].  فقتال الباغية حتى تفيء قتال شرعي، والمقتول في ذلك ليس داخلًا في الحديث؛ لأنه مأمور بالقتال، فالمقتول في هذا شهيد، والقاتل الذي يقاتل -وهو باغي- هو الذي على خطر، أما من قاتل لإزالة البغي، ولإيقاف الباغية عند حدها، ثم قتل؛ فهو شهيد، وإنما الخطر على مقتول الباغية التي أبت أن ترجع الحق، هذا هو الذي عليه الوعيد، وعليه الغضب؛ لأنه بغى، واعتدى، ولم يرجع عن خطئه، وضلاله، وهكذا المتقاتلون ظلمًا، وعدوانًا على الرياسات، أو على أمور فيما بينهم، أو على أشياء فيما بينهم من أحقاد، وشحناء هؤلاء داخلون في الحديث، ولا حول، ولا قوة إلا بالله. وأما ما جرى من القتال في فلسطين، وفي لبنان، وبين البعثيين، وبين الرافضة، فهذه أمور لها أسبابها وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ [فصلت:46] لما حصل من هذا القتال، وهذه الفتن كلها بأسباب الذنوب، والمعاصي، والغواية، والضلال من بعض أولئك وَمَا ظَلَمْنَاهُمْ، وَلَكِنْ كَانُوا هُمُ الظَّالِمِينَ [الزخرف:76] وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ [فصلت:46] وقال سبحانه: وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ، وَيَعْفُو عَنْ كَثِيرٍ [الشورى:30] فما سلط اليهود إلا بذنوبنا، وما جرى في بيروت من العذاب، والشر، والحروب الكثيرة، ووقعت السموم إلا بسبب ما وقع من البعض من الكفر، وفي الآخر من المعاصي، والشرور الكثيرة. وهكذا ما جرى على العراق، وما جرى على الشيعة في إيران، كل هذا بأسباب ما فعلوا، وما قدموا، الرافضة عندهم من الشر، والفساد، وسب الصحابة -رضي الله عنهم وأرضاهم- وعبادة أهل البيت بالشرك، وعبادة القبور، والبناء عليها، وعبادتها.","link":"https://binbaz.org.sa/fatwas/2738/معنى-حديث-اذا-التقى-المسلمان-بسيفيهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1238.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":6915,"question":"الذي يتزوج، ويخرج عن أهله، ما حكمه إذا أرغمته زوجته بالخروج لوحدنا في بيت عن أهلنا، ولم نقطعهما، بل نصلهما كلما غبنا مدة قليلة عنهما، مع ذكر الدليل، شاكرين تجاوبكم، ولكم تحياتنا؟","title":"حكم من تزوج وأراد الخروج عن أهله","answer":"الجواب: إذا خرج الولد عن والديه لأسباب اقتضت ذلك بإذنهما، وسماحهما؛ فلا بأس، إذا سمح الوالدان، وأذنا له في الخروج؛ فلا شيء في هذا؛ لأن المرأة قد لا تناسبهما، وقد لا تستقيم معهما، فإذا سمحا له بالخروج في بيت وحده؛ فلا حرج عليه، ولا بأس عليه، وليس هذا من القطيعة. إنما الكلام فيما إذا لم يسمحا، هذا هو محل البحث، إذا لم يسمحا له بالخروج، ولم تستقمْ الحال بينه وبينهما، هذا هو محل النظر، هل يقطعهما؟ هل يعصيهما؟ هل يطلق المرأة؟ هذا هو محل النظر، أما إذا سمحا، وأذنا له بالخروج؛ فلا شيء عليه، ولكن إذا لم يسمحا؛ فالإنسان ينظر، وليتأمل، فإن كانت المرأة أساءت إليهما، ولم تحسن صحبتهما؛ فهذه لا خير فيها؛ فينبغي إبدالها، وطلاقها، ويعطيه الله خيرًا منها وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2].  أما إذا كانا هما اللذان أساءا إليها، وهي محسنة إليهما، وهي طيبة الدين، والأخلاق، وقائمة بحقهما من الخدمة، وغير ذلك، ولكنهما يبغضانها لأسباب أخرى؛ فهذا هو محل نظر، لا يعجل، يجتهد في ارضائهما، والكلام الطيب معهما، ويبين حال المرأة، وحاجته إليها، وأنها لم تسِئْ إليهما، ولم تقم إلا بالخير، لعل الله يهديهما، فيكفا عن إلزامه بطلاقها، ولا يخرج، ولا يعجل في الخروج، بل يطمئن. والذي يظهر أنها إذا كانت لم تسِئْ؛ لا يلزمه طلاقها؛ لأنهما هما اللذان أساءا إليها، وأساءا إليه، ولكن يرفق بهما، ويجتهد في برهما، والإحسان إليهما، والصبر على ما قد يقع منهما من الأذى حتى يفرج الله، ولا يعجل في الطلاق؛ لأن المرأة الصالحة قل أن يوجد مثلها بعد ذلك. السؤال: وادعت المرأة أنها لا تستريح في العيش مع أمه، ولا بد أن يقيم لها بيتًا خارج القرية؟ الجواب: هذا ينظر فيه، إن سمحا له؛ فلا إشكال، وإذا لم يسمحا له وهما في حاجة إليه؛ فليطلقها، وليصبر معهما؛ حتى يأتي الله بامرأة تصبر عليهما.  أما إذا كان لا يستطيع طلاقها؛ لأنه فقير، وإذا طلقها قد ينضر، وقد يصيبه ضرر عظيم في عدم وجود زوجة، وعدم القدرة على الزوجة؛ فليستسمحهما، ولا يعجل في الأمور، ولعل إخوته يقومون بالواجب، وهو معذور في هذه الحالة؛ لأن الطاعة تكون في المعروف إنما الطاعة في المعروف.  وليس طلاقها -وهي مستقيمة- ليس طلاقها من المعروف إذا كانت طيبة في دينها، وفي أخلاقها، ولم تسِئْ إليهما، ولكن لم تستقم الحال معهما، إما لبخل والديه، وإما لسوء معاملة أولادهما الآخرين، أو بناتهما، أو غير ذلك. إذا كان هناك أسباب أخرى؛ فلا يعجل في الطلاق ما دامت صالحة في نفسها الزوجة، أو كذلك إذا كان عاجزًا عن تحصيل غيرها، فلا يعجل إلا إذا كانت في نفسها سيئة، غير مستقيمة، أو غير مستقيمة معهما، بل تؤذيهما، فإذا كانت غير صالحة في نفسها، أو غير صالحة معهما تؤذيهمان وتسيء خلقها معهماح فليطلقها، وسوف يعطيه الله خيرًا منها وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2].","link":"https://binbaz.org.sa/fatwas/2845/حكم-من-تزوج-واراد-الخروج-عن-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1293.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":6950,"question":"تناقش الآن مشكلة في الضفة الغربية التي احتلها اليهود منذ 67، وهذه المشكلة هي: هل يجوز نهب أموال اليهود، وسرقتها، وأخذها بأي طريق كان؛ ذلك بأنهم أعداؤنا، والذين سرقوا أموالنا، وأرضنا، وسرقوا كرامتنا، أود أن أسمع رأي سماحتكم في هذا الموضوع، هل حصل في تاريخنا الإسلامي ما يشبه هذه المشكلة؟ علمًا بأن هناك من المشايخ من أفتى بجواز هذا الأمر، وآخرون أفتوا بعدمه؟","title":"حكم أخذ أموال الحربيين","answer":"الجواب: نعم نعم، لمن بينهم وبينهم الحرب أن يأخذوا أموالهم، وينهبوها، ويسرقوها؛ لأنهم حرب للمسلمين، وخصومهم. أما إن كان اليهود في بلد أدرك فيها الأمن، لا يحل أمانه إذا كان في بلد قد أمن فيها، في مصر، أو في أي مكان قد أمن فيها، لا يتعدى عليه حتى يخرج من بلاده، حتى يذهب عن بلادهم. أما من بينهم وبينهم الحرب، كالفلسطينيين؛ فإنهم لهم أن يأخذوا منهم ما شاؤوا، ولهم ما قدروا عليه، ويسرقون أولادهم، وبناتهم، وأموالهم، وغير ذلك.","link":"https://binbaz.org.sa/fatwas/2880/حكم-اخذ-اموال-الحربيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1328.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":7089,"question":"إذا ظهرت المنكرات في قوم؛ فإن الله سوف يعذبهم؛ لحديث عائشة -رضي الله عنها- قالت: يا رسول الله أنهلك وفينا الصالحون؟ قال: نعم وبهم يبدأ العذاب إذًا أيها الصالحون لماذا انتشار هذا؟ وما موقف العلماء الساكتين، وكأن على رؤوسهم الطير؟ وهل انتشار الربا والمسجلات والفيديو وبيع المجلات الخليعة وغيرها، أليس هذا فيه ظهور المنكرات إلى آخره؟","title":"بيان حديث: «أنهلك وفينا الصالحون»","answer":"الجواب:\n\nهذا الحديث عن زينب ليس عن عائشة، وليس هذا لفظه بالتمام، عن زينب بنت جحش أم المؤمنين -رضي الله عنها- أن النبي ﷺ دخل عليها غضبان يقول: ويل للعرب من شر قد اقترب، فتح اليوم من ردم يأجوج ومأجوج مثل هذا وحلق بين أصبعيه السباحة، والوسطى، فقالت له زينب -رضي الله عنها-: يا رسول الله أنهلك وفينا الصالحون؟! قال: نعم إذا كثر الخبث! يعني إذا كثرت المعاصي؛ عم الهلاك، ولا حول ولا قوة إلا بالله.\n\nعمت العقوبات كما قال النبي في الحديث الآخر، في الحديث الصحيح يقول ﷺ: إن الناس إذا رأوا المنكر فلم يغيروه؛ أوشك أن يعمهم الله بعقابه ولا فيه بأنه يبدأ بالصالحين، ليس في الحديث هذا، إنما هذا في أثر آخر: أن ملكًا من الملائكة أمر أن يعذب قرية، فقال: إن فيها فلانًا عبدك الصالح فلان، قال: به فابدأ، فإنه لم يتغير فيَّ قط ،  هذا خبر آخر إسرائيلي.\n\nوأما قولك: لماذا لا تنكرون؟ ولماذا ما أنكروا، ومن قال لك: إنهم ما أنكروا؟ هل أحطت بقلوبهم، وعرفت ما عندهم! قد أنكر العلماء، وكتبوا لولاة الأمور، وبينوا ما يجب، وبينوا أن هذه منكرات، وكلموهم مرات -نسأل الله لنا ولكم ولهم التوفيق-.\n\nلا يجوز للإنسان أن يقول: ما أنكروا وهو ما يعلم، ليس من شرط الإنكار أن يعم في المساجد أن فلانًا أنكر كذا، وفلانًا أنكر كذا، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/3102/بيان-حديث-انهلك-وفينا-الصالحون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1479.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7247,"question":"من سره أن يبسط له في رزقه، وينسأ له في أجله؛ فليصل رحمه ما معنى الحديث؟ وكيف يطول عمر من وصل الرحم، وفي حديث آخر: أن ابن آدم يكتب أجله وهو في بطن أمه؟","title":"معنى حديث: «من سره أن يبسط له في رزقه»","answer":"الجواب:\n\nسبق الكلام في هذا الحديث الصحيح، ومعنى ذلك: أن الله -جل وعلا- قد سبق في علمه أن هذا الذي وصل رحمه؛ يطول عمره، وينسأ في أجله بأسباب صلة رحمه، والآخر بضد ذلك، كل شيء بقدر الله -جل وعلا- فالإنسان يتعاطى الأسباب، والأمور مقدرة، والله حث على الأسباب التي شرعها وأمر بها، وقد سبق في علمه من يفعل ومن لا يفعل.","link":"https://binbaz.org.sa/fatwas/3318/معنى-حديث-من-سره-ان-يبسط-له-في-رزقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1642.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7254,"question":"من سره أن يبسط له في رزقه، وينسأ له في أجله؛ فليصل رحمه ما معنى الحديث؟ وكيف يطول عمر من وصل الرحم، وفي حديث آخر: أن ابن آدم يكتب أجله وهو في بطن أمه؟","title":"معنى حديث: «من سره أن يبسط له في رزقه»","answer":"الجواب:\n\nسبق الكلام في هذا الحديث الصحيح، ومعنى ذلك: أن الله -جل وعلا- قد سبق في علمه أن هذا الذي وصل رحمه؛ يطول عمره، وينسأ في أجله بأسباب صلة رحمه، والآخر بضد ذلك، كل شيء بقدر الله -جل وعلا- فالإنسان يتعاطى الأسباب، والأمور مقدرة، والله حث على الأسباب التي شرعها وأمر بها، وقد سبق في علمه من يفعل ومن لا يفعل.","link":"https://binbaz.org.sa/fatwas/3318/معنى-حديث-من-سره-ان-يبسط-له-في-رزقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1642.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7326,"question":"قول النبي ﷺ: من سأل لي الوسيلة؛ حلت له شفاعتي لو وضحتم؟","title":"شرح قوله عليه الصلاة والسلام: «من سأل لي الوسيلة»","answer":"الجواب: هذا يشرع للمؤمن بعد الأذان، إذا أجاب المؤذن يقول النبي ﷺ: إذا سمعتم المؤذن؛ فقولوا مثل ما يقول، ثم صلوا علي فإنه من صلى علي واحدة؛ صلى الله عليه بها عشرًا اللهم صل عليه وسلم ثم سلوا الله لي الوسيلة فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة؛ حلت له شفاعتي يوم القيامة وفي لفظ آخر حلت له الشفاعة.  هذه الوسيلة منزلة في الجنة، قصر في الجنة عظيم لنبينا -عليه الصلاة والسلام- فينبغي سؤال الله أن يعطيه هذه الوسيلة، وفي اللفظ الآخر: من قال حين يسمع النداء: اللهم رب هذه الدعوة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه المقام المحمود الذي وعدته، إنك لا تخلف الميعاد هذا مشروع أيضًا بعد الأذان، دعاء للنبي ﷺ أن الله يعطيه الوسيلة، وهي منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، قال النبي ﷺ: وأرجو أن أكون أنا هو عليه الصلاة والسلام. السؤال: شفاعته في الآخرة؟ الجواب: شفاعته تطلب من الله، هو يشفع للأمة يوم القيامة حتى يقضى بينهم، حتى يدخل المؤمنون الجنة، لكن تقول: اللهم شفع في نبيك، اللهم اجعلني من أهل شفاعته، اللهم لا تحرمني شفاعته، لا تقول: يا رسول الله اشفع لي، ما تدعوه بعد وفاته ﷺ تطلب الله أن الله يشفعه فيك، اللهم شفع في نبيك، اللهم اجعلني من أهل شفاعته، اللهم لا تحرمني شفاعته يا ربي، هكذا المؤمن يسأل ربه قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا [الزمر:44].  أما في حياته لا بأس إن كان حيًا بيننا، بين أصحابه يقول: يا رسول الله اشفع لنا، ادع الله لنا، وهكذا يوم القيامة عندما يقوم الناس من قبورهم، ويجتمعون يقولون له، يجتمع المؤمنون ويقولون له: يا رسول الله اشفع لنا حتى يقضى بيننا.","link":"https://binbaz.org.sa/fatwas/3405/شرح-قوله-عليه-الصلاة-والسلام-من-سال-لي-الوسيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1718.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7336,"question":"ما معنى: من تقرب مني شبرًا تقربت منه ذراعًا، ومن أتاني يمشي أتيته هرولة؟","title":"معنى حديث: «من تقرب مني شبراً»","answer":"الجواب:  هذا حديث صحيح عن النبي ﷺ: قال الله : أنا عند ظن عبدي بي، وأنا معه حين يذكرني، فإن ذكرني في نفسه؛ ذكرته في نفسي، وإن ذكرني في ملإ؛ ذكرته في ملإ خير منه، وإن تقرب إلي شبرًا؛ تقربت منه ذراعًا، وإن تقرب مني ذراعًا؛ تقربت منه باعًا، وإن أتاني يمشي؛ أتيته هرولة هذا من الرب  حث للعباد على ذكره والمسارعة إلى طاعته . وتفسيرها هذا إليه ، لا يعلم كيفية هذا التقرب منه -جل وعلا- إلا هو  مثل ما نقول في استوائه، ونزوله، وغضبه، ورحمته، كل هذه الصفات تليق به، لا يشابه فيها خلقه، ولا يعلم كيفيتها سواه  فلا نكيف تقربه، ولا نكيف مجيئه ومشيه وهرولته، لا نكيف ذلك، بل نقول على الوجه اللائق بالله  لكن من ثمرة هذا ومن مقتضاه أنه أسرع بالخير إلينا  وأرحم بنا -جل وعلا-.","link":"https://binbaz.org.sa/fatwas/3403/معنى-حديث-من-تقرب-مني-شبرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1716.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":7451,"question":"هل حديث مضايقة الكفار إلى أضيق الطريق صحيح؟ وإذا كان صحيحًا فكيف يوفق بينه وبين قول الله تعالى: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ [الممتحنة:8] إلى آخر الآية؟","title":"الجمع بين حديث مضايقة الكفار وآية الإحسان إليهم","answer":"الجواب: الحديث صحيح، قول النبي ﷺ: لا تبدؤوا اليهود ولا النصارى بالسلام، وإذا لقيتموهم في طريق فاضطروهم إلى أضيقه أخرجه مسلم في صحيحه، المعنى أنهم لا يبدؤون بالسلام، لكن إذا سلموا رد عليهم، ولا يترك لهم وسط الطريق بل يترك لهم حافات الطريق إذا استطاع المسلمون ذلك، وليس بينه منافاة وبين الآية لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ [الممتحنة:8] هذا ممكن وهذا ممكن، يبرهم ويقسط إليهم إذا رأى ذلك لفقرهم وحاجتهم، ولكن مع ذلك يفعل بما قال النبي ﷺ في اضطرارهم إلى أضيق الطريق وألا يكون لهم وسط الطريق، تكون لهم حافات الطريق والمسلمون في وسطه.  هذا ممكن وهذا ممكن ولا منافاة بين هذا وهذا، أن يقسط إليهم ويحسن إليهم إذا كان محتاجًا أو فقيرًا أو قريبًا، ومع ذلك لا يبدأه بالسلام، ولا يجعل له وسط الطريق إذا استطاع ذلك، وهذا كله معناه مضايقتهم حتى يدخلوا في الإسلام إذا كانوا بين المسلمين، إذا عرفوا المضايقة من المسلمين وأنهم لا يبدؤونهم بالسلام وأنهم يضطرونهم إلى أضيق الطريق صار هذا من أعظم الأسباب في دخولهم الإسلام وتركهم الباطل الذي هو سبب إذلال المسلمين لهم وعدم بدئهم بالسلام إلى آخره.","link":"https://binbaz.org.sa/fatwas/3528/الجمع-بين-حديث-مضايقة-الكفار-واية-الاحسان-اليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1832.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":15182,"question":"أيضًا محمد طه، من سوريا، لديه سؤال آخر، يقول: قال ﷺ: يقاتلكم اليهود وتنتصرون عليهم يقول: إنه يتوقع أنه إذا كان هذا الحديث صحيحًا، فعهدنا الذي نعيشه الآن هو العهد الذي يتحدث عنه ﷺ، فما هو رأيكم؟ أرجو أن توضحوا لي هذا الحديث؛ لأنه دائمًا يقع بيننا مشادة في الكلام عنه.وفقكم الله.","title":"بيان حديث قتال المسلمين لليهود، وفي أي زمن؟","answer":"الجواب: الحديث صحيح، رواه الشيخان البخاري ومسلم في الصحيحين وغيرهما، ولفظه: يقاتل المسلمون اليهود، فينصرون عليهم، حتى يقول الشجر والحجر: يا مسلم، يا عبدالله، هذا يهودي تعال فاقتله أو قريب من هذا اللفظ. فالمقصود: أنه ثابت عن رسول الله ﷺ، وأن المسلمين يقاتلون اليهود، وأنهم ينصرون عليهم حتى إن الحجر والشجر يقول للمسلم: يا عبدالله، تعال هذا يهودي تعال فاقتله. أما كون ذلك في وقتنا هذا محل نظر، فإن الذي يقاتلهم المسلمون، والمقاتلون الآن ليسوا على المستوى الكامل من جهة الإسلام، فيهم المسلم وفيهم غير المسلم، وليس هناك تطبيق فيما بلغنا من المسلمين هناك للشريعة المطهرة كما ينبغي، بل هناك العاصي، وهناك الكافر، وهناك المسلم المستقيم، فالقتال الذي أخبر به النبي ﷺ يكون من المسلمين الملتزمين المستقيمين، فلهذا ينصرهم الله على اليهود بسبب استقامتهم على دين الإسلام ونصرهم لدين الله، فيحتمل أن يكون هذا بعد وقت تتحسن فيه أحوال المسلمين، ويجتمعون على الحق والهدى فينصرون عليهم، ويحتمل أن هذا في وقت عيسى كما هو معلوم، فإنه في وقت عيسى يقتل اليهود، وينصر الله عيسى والمسلمين عليهم، ويقتل الدجال هذا لا شك في وقت عيسى، لكن يحتمل أن يقع قبل عيسى، وأن المسلمين تتحسن أحوالهم وتستقيم أمورهم على شريعة الله، ويقودهم أمير صالح، أو إمام صالح يقودهم إلى الحق والهدى، ويستقيمون على شريعة الله، ثم يتوجهون لقتال اليهود، فينصرون عليهم، هذا كله محل احتمال. أما في وقت عيسى فلا شك أنه يقتلهم، وأنه ينصر عليهم -عليه الصلاة والسلام- مع المسلمين عند قتله للدجال، نعم.","link":"https://binbaz.org.sa/fatwas/13685/بيان-حديث-قتال-المسلمين-لليهود-وفي-اي-زمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_666/nour_66602.mp3","categories":["شروح الحديث","الجهاد والسير"]},{"id":17214,"question":"هنا رسالة من المستمع: محمد أبو بكر باحسين من الجمهورية اليمنية حضرموت، أخونا له جمع من الأسئلة في أحدها يقول: قرأت في كتاب للدكتور عبدالله عزام -رحمه الله وأسكنه فسيح جناته- بعنوان: (آيات الرحمن في جهاد الأفغان) أن الكفار إذا كانوا في بلادهم، ولا يعدون لحرب المسلمين فإن حربهم على المسلمين في هذه الحالة فرض كفاية، ومعروف أن فرض الكفاية واجب على بعض المسلمين، فهل المسلمون اليوم يقومون بذلك؟","title":"أحوال فرض العين والكفاية في الجهاد","answer":"الجواب: إذا اعتدى الكفار على المسلمين؛ وجب على المعتدى عليهم جميعًا أن يدفعوا الشر عنهم، وصار فرض عين، إذا حضر الصفين، أو هجم عليه العدو، أو استنفره الإمام، في هذه.. في هذه المسائل الثلاث، يجب فرض عين، إذا استنفر الإمام الناس، أو حضر الصفين، أو هجم عليهم العدو في بلادهم؛ وجب عليهم أن يدافعوا. أما جهاد الكفار طلبًا، والذهاب إليهم للجهاد، فهذا فرض كفاية، على ولي الأمر أن يعد لذلك العدة، لجهاد الكفار حسب الطاقة إذا استطاع ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16040/احوال-فرض-العين-والكفاية-في-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72310.mp3","categories":["الجهاد والسير"]},{"id":17815,"question":"تقول السائلة يا سماحة الشيخ: من هو الشهيد بالمعنى الشرعي؟","title":"من هو الشهيد؟","answer":"الجواب: بيَّنه النبي ﷺ، الشهداء كثير وأعظمهم وأفضلهم الشهيد في سبيل الله، المقتول في سبيل الله، ومنهم المبطون اللي يموت بالبطن، ومنهم من يموت بالطاعون هذا أيضًا شهيد؛ شهيد الطاعون، والمبطون شهيد مع جماعة بيَّنهم النبي عليه الصلاة والسلام لكن أفضلهم وأعظمهم الشهيد في المعركة، نعم. فصاحب الهدم شهيد وصاحب الحرق شهيد والمرأة تموت بسبب الولد بسبب النفاس شهيدة. نعم.","link":"https://binbaz.org.sa/fatwas/16808/من-هو-الشهيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77821.mp3","categories":["الجهاد والسير"]},{"id":18696,"question":"من ليبيا هذه رسالة بعث بها مستمع من هناك هو (خ. أ. ح) أخونا يقول في رسالته: أنا طالب في الجامعة، ومن خلال قراءتي لكتاب الإسلام للمستشرق هنري ماسيه، والذي ترجمه بهيج شعبان، والذي علق عليه وقدم له سماحة الدكتور مصطفى الرافعي، وسماحة الشيخ محمد جواد مغنية، بقيت في ذهني مسألتان لم توضح جيدًا، وأعتبرهما مسألتان هامتان، وهما: نعلم أن الشهادة هي التي يقوم بها مسلم يحارب لأجل إيمانه ويموت في سبيله مجاهدًا فيصبح عند ذلك شهيدًا، ولكن فكرة قابلية التضحية خلقت الاضطراب في مفهوم الشهادة والانتحار عندي.فوجهوني جزاكم الله خيرًا.","title":"الفرق بين الشهادة في سبيل الله والعمليات الاستشهادية","answer":"الجواب: الشهادة التي أعد الله لأهلها الجنة، ومدح أهلها هي التي تصدر عن رغبة فيما عند الله، وإخلاص لله، والجهاد في سبيله  سأل رجل الرسول -عليه الصلاة والسلام-، قال: «يا رسول الله، أرأيت إن قتلت في سبيل الله أأدخل الجنة؟ أتكفر عني خطاياي؟ -أو كما قال- فقال -عليه الصلاة والسلام-: نعم، إن قتلت صابرًا محتسبًا مقبلًا غير مدبر. فالمؤمن الذي يقاتل في سبيل الله، يرجو ثواب الله، ويريد نصر دين الله، فهذا هو المجاهد في سبيل الله، وهو الشهيد إذا قتل، له حكم الشهادة التي وعد الله أهلها الجنة. أما من جهة حكم الدنيا فكل من قتل في سبيل الله لا يغسل ولا يصلى عليه، والعمل على الظاهر، ونيته إلى الله ، فإذا قتل في سبيل الله، مات في المعركة بالقتل لا يغسل ولا يصلى عليه، بل يدفن في ثيابه، كما فعل النبي ﷺ في شهداء يوم أحد. وأما حكمه عند الله فإن قتل صابرًا محتسبًا مقبلًا غير مدبر موحدًا لله قاصدًا وجهه الكريم، فإنه تكفر عنه خطاياه، ويكون من أهل الجنة، لكن جاء في الروايات الأخرى عن الرسول -عليه الصلاة والسلام- أنه قال: إلا الدين. قال: أخبرني جبرائيل آنفًا. فالدين معناه: أن صاحبه لا يضيع عليه دينه، بل يعطى حقه، إما بأن يرضيه الله عنه يوم القيامة من فضله وإحسانه، وإما أن يعطى من حسنات هذا الشهيد ما يقابل الدين، فالشهيد على خير، وصاحب الدين لا يضيع حقه، بل الله يرضيه عنه  بما يشاء -جل وعلا-، نعم. المقدم: جزاكم الله خيرًا، موضوع الفداء والاستشهاد في سبيل الله شيخ عبد العزيز كأنه يطلب المقارنة بينهما أو التفريق بينهما؟ الشيخ: ما أفهم مراده بالفداء. المقدم: كونه يكون فدائيًا. الشيخ: إذا كان قصده بذلك أن يبارز الناس، وأن يجتهد في مهاجمة الأعداء، ولو قتل في سبيل الله، هذا مطلوب، إذا كان العدو من الأعداء من الكفرة المعروفين، وجاهد في سبيل الله، وأقدم على الجهاد، ولو قتل يرجى له الخير العظيم ولو قتل، مثلما فعل أنس بن النضر عندما انصرف الناس يوم أحد تقدم إلى الجهاد حتى قتل  الناس منصرفون وهو متقدم إلى العدو، وجاهد حتى قتل، فوجدوا فيه بضعًا وثمانين ما بين ضربة بسيف، وطعنة برمح  وأرضاه. فالحاصل: أن الفداء وهو التقدم إلى العدو حرصًا على الشهادة في سبيل الله وحرصًا على قتال الأعداء هذا فيه فضل عظيم وخير كثير. نعم. المقدم: إذًا: لا يعد هذا من الانتحار؟ الشيخ: ما دام لله، إذا كان لله لا رياء ولا سمعة، إذا كان لله ليس قصده الرياء ولا السمعة، وليس من قصده الوطن، إنما قصده القتال في سبيل الله، فهذا له خير عظيم. المقدم: جزاكم الله خيرًا، ولا يعد هذا من الانتحار؟ الشيخ: ما يعد من الانتحار، لا. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17797/الفرق-بين-الشهادة-في-سبيل-الله-والعمليات-الاستشهادية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92006.mp3","categories":["الجهاد والسير"]},{"id":18807,"question":"سماحة الشيخ، لا أدري سمعت من أحد العلماء: أن الجهاد بالمال يعدل الجهاد بالنفس، رأيكم في هذا؟","title":"فضيلة الجهاد بالمال والنفس","answer":"الجواب: الله سبحانه قدم الجهاد بالمال على الجهاد بالنفس في غالب الآيات. المقدم: الجهاد بالمال مقدم. الشيخ: قدمه على الجهاد بالنفس؛ لقوله تعالى: انفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنفُسِكُمْ فِي سَبِيلِ اللَّهِ [التوبة:41] وقال تعالى: أَجَعَلْتُمْ سِقَايَةَ الْحَاجِّ وَعِمَارَةَ الْمَسْجِدِ الْحَرَامِ كَمَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الآخِرِ وَجَاهَدَ فِي سَبِيلِ اللَّهِ لا يَسْتَوُونَ عِنْدَ اللَّهِ وَاللَّهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ [التوبة:19]. فالمقصود: أن الجهاد في سبيل الله له شأن عظيم، وهو بالمال أفضل من بعض الوجوه، وبالنفس أفضل من بعض الوجوه، فالنفس أغلى شيء عند الإنسان، فإذا جاهد بنفسه فهذا أفضل الجهاد؛ لأنه جاهد بنفسه. لكن قدم الله المال؛ لأن المال ينفع في جهات كثيرة، يستطاع أن يستأجر به المجاهد، يستطاع أن يجهز به المجاهد، يستطاع أن يشترى به السلاح، يشترى به الطعام والشراب، تشترى به الكسوة، تشتري به المئونة الذخيرة، فنفع المال متنوع. أما الجهاد بالنفس فهو جهاد خاص، وهو بذله نفسه في سبيل الله ، لكن ما يستفاد من المال أنواع منوعة، كثيرة.، أصناف؛ فلهذا قدم في غالب الآيات، وذكرت النفس في آية واحدة في قوله تعالى: إِنَّ اللَّهَ اشْتَرَى مِنَ الْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَالَهُمْ بِأَنَّ لَهُمُ الْجَنَّةَ [التوبة:111] فلما كان المقام مقام تقديم النفس وتقديم المال، فتقديم النفس أعظم من تقديم المال، وأغلى عند الله وعند المؤمنين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17953/فضيلة-الجهاد-بالمال-والنفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_877/nour_87705.mp3","categories":["الجهاد والسير"]},{"id":19265,"question":"أيضًا أختنا تقول: أخبروني عن الشهداء؟ جزاكم الله خيرًا.","title":"أنواع الشهداء","answer":"الجواب: الشهداء أنواع، أفضلهم الشهيد في سبيل الله، الذي يقتل في قتال الكفار، أو قتال البغاة، ويموت في المعركة بنية صالحة، يقصد ثواب الله، ويريد نصر دينه، فهذا هو أفضل الشهداء، والله وعدهم الجنة، ومن الشهداء من يموت بالطاعون مرض الطاعون المعروف، ومرض البطن وهو الإسهال، أو بالغرق أو بالهدم، كل هؤلاء من الشهداء كما قال النبي عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/18469/انواع-الشهداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89213.mp3","categories":["الجهاد والسير"]}]
